-- Fill missing zhTW quest_offer_reward_locale rows, converted from zhCN via OpenCC s2twp,
-- with known-official zone-name corrections applied
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 1 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (1,'zhTW','恭喜。給你10金幣和一些天賦。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 2 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (2,'zhTW','真不錯，$N……沙普塔隆的爪子可不是那麼容易可以得到的！看來你的梣谷狩獵之行很順利啊！$B$B伐木場的工人總是會受到沙普塔隆的襲擊。毫無疑問的，當這頭猛獸被你殺死的訊息傳出去之後，很多歌頌你英勇事蹟的歌謠肯定會在梣谷營地及伐木場流傳開來的！',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 5 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (5,'zhTW','你想要黑蟹蛋糕？也許我可以做一點給你……',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 6 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6,'zhTW','哈，你幹掉他了！你為艾爾文森林做了一件好事，當然咯，你也獲得了賞金。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 7 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (7,'zhTW','幹得好，$N。那些狗頭人不過是些小賊和懦夫，不過如果他們數量太多的話，還是會對我們構成威脅。而且，暴風城要面臨的威脅已經足夠多了。$B$B我為你成功的清剿行動表示我的敬意。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 8 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8,'zhTW','哦？有我的信？真是太好了！我一直在期待喪鐘鎮裡親愛的老母親音信，她是那麼的崇高與聖潔……我想知道她近況如何。$B$B什麼？你覺得太開心？你不相信這是真的？$B$B啊，那你快滾吧，這封信是誰寫給我的，跟你無關。走吧！快滾！$B$B等你有錢的時候再來吧！沒出息的東西！$B$B用不了多久啊，你一定又經過什麼冒險啊！什麼類似愚蠢的事情，想回來休息。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 9 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9,'zhTW','幹得漂亮，夥計。你為自己掙到了不菲的酬勞呀。誰知道呢，或許有一天西部荒野又會富饒如初吧。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 10 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10,'zhTW','年輕的謝申克是個好侏儒。希望他沒有白白犧牲，他的勘探裝置中應該記錄了一些有用的東西。$B$B看來我們一定要著手處理這些蟲子了。它們是如此的貪婪和狡猾，從現在的情況來看，它們可能是被某個更強大的力量所控制著！如果真是這樣，不僅是加基森，整個沙漠都要遭殃了！',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 11 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11,'zhTW','我知道你肯定忙了好一陣子！謝謝你，$N。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 12 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12,'zhTW','做得好，$N。我的斥候見證了你英勇的行為。你也出色地證明了自己的實力。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 13 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13,'zhTW','因你這次勇敢的行動，我們已經確信你對人民軍有著重要的價值。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 14 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (14,'zhTW','在離開洛丹倫那片受汙染的土地之後，我回到了這裡，回到了我的故鄉，被迫要面對一種這樣嚴酷的形勢。但西部荒野仍然還有希望，你在戰鬥中的英勇與無畏告訴我，你正揹負著無上的榮光與我們並肩作戰，幫助我們完成偉大的事業。人民軍中能有你這樣的$C，讓我感到無比自豪。願聖光永遠照耀著你。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 15 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (15,'zhTW','我真不想聽到這些佔據了我們礦洞狗頭人的事情？真糟糕！他們是幹不出什麼好事來的。來，這是你的酬勞。另外，補給完畢以後再來找我一下。我希望你可以再去礦洞一次……',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 16 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (16,'zhTW','謝謝，$N！如果你還想再交換的話就回來找我吧！',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 17 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (17,'zhTW','做得好，$N，你再一次證明了自己的價值！研究這種蘑菇肯定會非常有趣！$B$B根據我的承諾，來嚐嚐我收藏多年的陳年好酒吧！$B$B如果你是個有經驗的鍊金師，那我們還可以進行其它的合作。不管怎麼樣，我要再次感謝你對我的幫助。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 18 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (18,'zhTW','你帶回著面罩回來了，幹得好。暴風城軍方感謝你的幫助。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 19 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (19,'zhTW','薩瑞爾祖恩是個卑鄙狡猾的獸人。你做得很好——我敢說你一定花了不少工夫才把他撂倒的。這是你的酬勞，$N。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 20 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (20,'zhTW','這下獸人的數量少太多了，我們也就不必太擔心了，謝謝你。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 21 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (21,'zhTW','我再次對你表示敬意，暴風城軍方也感謝你。或許礦洞裡還會有殘餘的狗頭人活動，但我將會派遣其他人去解決他們。我們另有更重要的任務派給你。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 22 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (22,'zhTW','這些豬肝真新鮮，$N！太感謝你了。薩丁和我今天晚上就能吃一頓美味餡餅啦。這是給你的，感謝你幫我們找到豬肝。我可不能讓你這樣可愛的小$C給餓著了，對吧？',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 23 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (23,'zhTW','啊，烏薩苟斯的爪子！你的身手真是令人印象深刻，$C。死在它爪下的生命不計其數，這塊新月形毫無疑問的證明它曾被那些隱藏在梣谷中的夜嚮導訓練過。烏薩苟斯……曾經是這片本地最強大的野獸之一。能殺死這樣的野獸表示你的意志和技藝都是無以倫比的。$B$B你的祖先會為你感到驕傲的！',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 24 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (24,'zhTW','這是$N，在梣谷狩獵中又一次的勝利！做得好！毫無疑問地，薩杜布拉的頭顱是件絕佳的戰利品。$B$B薩杜布拉的殘暴令它惡名昭彰，任何往西邊去的旅行者，特別是那些徒步轉至佐拉姆海岸的旅行者，總是會因為這頭猛獸的存在而膽戰心驚。謝謝你，現在這個危險已經被消除了。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 25 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (25,'zhTW','啊，我聽說有個$C像貧瘠之地的風暴一樣席捲了整個湖泊。也許我們可以在那兒設立一個崗哨，密切注視我們的聯盟朋友們。嗯，我們必須保持低調……$B$B你似乎相當能幹，這裡和石爪山之間的交通又恢復暢通了。拿著——這是你應得的。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 26 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (26,'zhTW','你好，年輕的德魯伊。現在是讓你瞭解我們的水棲形態的時候了。這種形態能讓你在水中活動自如，你將發現它是一種非常實用的形態，是神對我們的恩賜……但你必須要透過自己的努力去獲得它。$B$B你將面對兩個考驗。首先要測試你在水中壓力下的作業能力，並掌握它。$B$B做好準備吧，試煉就要開始了。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 27 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (27,'zhTW','你好，年輕的德魯伊。現在是讓你瞭解我們的水棲形態的時候了。這種形態能讓你在水中活動自如，你將發現它是一種非常實用的形態，是神對我們的恩賜……但你必須要透過自己的努力去獲得它。$B$B你將面對兩個考驗。首先要測試你在水中壓力下的作業能力，並掌握它。$B$B做好準備吧，試煉就要開始了。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 28 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (28,'zhTW','嗯，又一個成功完成湖中試煉的德魯伊！做得好，我年輕的朋友。$B$B我是塔加里，月光林地及這座神殿的守護者，這是我的責任，也是我所擁有的特權。守護者雷姆洛斯指引著塞納里奧議會努力保持著自然的平衡，並且他的神殿正在為此做出巨大的貢獻。在這裡使用靈珠，即表示你認同這個地方在議會中的重要性。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 29 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (29,'zhTW','嗯，又一個成功完成湖中試煉的德魯伊！做得好，我年輕的朋友。$B$B我是塔加里，月光林地及這座神殿的守護者，這是我的責任，也是我所擁有的特權。守護者雷姆洛斯指引著塞納里奧議會努力保持著自然的平衡，並且他的神殿正在為此做出巨大的貢獻。在這裡使用靈珠，即表示你認同這個地方在議會中的重要性。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 30 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (30,'zhTW','你合成了海獅墜飾，$N，恭喜你。$B$B尋找墜飾的每項任務都告訴我們，敏捷和耐力的協調一致在水下是非常必要的。兩者不能獨存，而如果你不利用海獅的形態，那么這兩者均不能實現。$B$B好好記著我說的話，一旦你掌握了水棲形態的知識，就得依賴它所代表的這兩種特性了。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 31 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (31,'zhTW','很好，$N。你的祖先看到你有如此的成就，一定會非常高興的！你已經做好學習水棲形態的準備了，我很高興能將這項技能傳授給你。$B$B此外，為了對你在這兩次試煉中取得的成就表示讚許，我把這個給你。希望它能在你保持自然平衡的過程中對你有所幫助。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 32 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (32,'zhTW','這份報告……我以前確實對付過其中提到過的野獸。菲茲杜瑟很明智地讓你把這份報告送到我這裡來。$B$B這些生物會迅速吞噬塔納利斯的沙漠，它們將會是我們有史以來所要面臨的最大威脅。$N，記住這個名字：異種蠍。報告裡提到的這些昆蟲就是異種蠍，它們對部落和聯盟來說都是一個巨大的威脅。$B$B除非我們能夠早點意識到它的危害程度，否則後果不堪設想。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 33 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (33,'zhTW','真是太辛苦你了！我已經等不及要去煮狼肉了……$B$B我這裡有些東西你也許用得著……選一件吧！',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 34 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (34,'zhTW','哈哈，終於把這個禍害除掉了。多謝你，$N，你做了一件好事。今年花園裡的花一定會開得很茂盛！',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 35 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (35,'zhTW','沒錯，魚人已經在這裡落腳了，就在艾爾文森林東部的河流附近。我們不知道他們為什麼會出現在這裡，不過他們很有攻擊性，而且看起來並不是很笨。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 36 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (36,'zhTW','弗娜總是這麼可愛。我們這些留在西部荒野的人一定會非常想念她的，她是個典型的都市女孩，一定會很快就能適應暴風城的生活方式的。好啦，就聊這麼多啦！現在我們得開始做西部荒野燉肉啦！',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 37 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (37,'zhTW','雖然這具屍體已經殘缺不全，不過你發現屍體旁邊的一塊勳章上面刻著幾個字“步卒馬拉凱·史東”。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 38 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (38,'zhTW','放入秋葵會使肉湯變得非常濃郁芳香！現在我們再放入禿鷹肉，一點魚人的眼睛和美味的野豬鼻子，大功告成啦！為了答謝你的幫助，$N，來，我要請你先品嚐一下今天的第一鍋西部荒野燉肉！',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 39 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (39,'zhTW','嗯，這個訊息確實是很麻煩。我們的防守已經很薄弱了，羅爾夫和馬拉凱死在魚人的手上讓我們的處境更加不妙。$B$B如果我們不想些辦法的話，不用一個禮拜，這群長著腿的魚就會殺到閃金鎮來了！',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 40 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (40,'zhTW','對，我和雷米談過。他是一個很值得尊敬的商人，不過關於東部魚人的報告當前還不甚明瞭。$B$B我們會注意這件事情，但除非我接到有關魚人威脅的軍事報告，否則我們是不能輕率地派更多人去東部的。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 45 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (45,'zhTW','你在屍體的脖子上找到一塊金屬勳章，上面刻著“步卒羅爾夫·哈特弗德”。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 46 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (46,'zhTW','你拿到魚鰭了？太好了！治安官杜漢對艾爾文森林東部日益猖獗的魚人感到很擔憂，現在看來形勢已經在我們的控制之中了。$B$B你幫了我們的大忙，謝謝你。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 47 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (47,'zhTW','謝謝你的金砂，$N。這是該給你的錢，還有……這是我的一個合夥人給我的，也許會對你有用。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 49 AND `locale` = 'zhTW';
