INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (52,'zhTW','非常感謝你的幫助，$N。森林裡一定有什麼東西讓這些動物變得這麼瘋狂。$B$B不管那是什麼，我希望它不要再搞出什麼新名堂來了。',0);
