INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (54,'zhTW','哦，信上說你被暴風城的元帥授予執行副隊長的軍銜，恭喜！$B$B另外，祝你好運，保衛艾爾文森林可不是在野餐……天知道這麼多士兵忙來忙去都幹了些什麼，天知道他們都在為誰賣命！$B$B在這樣黑暗的日子裡，要站對立場都很困難啊……',0);
