INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (55,'zhTW','摩本特·費爾被打敗了。雖然黑騎兵還沒被徹底消滅，但是我又看到了本已消逝的希望。$B$B你完成了一個幾乎不可能完成的任務，你的事蹟會永遠被夜色鎮的人民傳頌。$B$B走吧，$N。也許有一天，命運還會把你帶回我這裡……',0);
