INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (58,'zhTW','作為守夜人的指揮官以及夜色鎮人民的代表，我對你的英勇及貢獻表示感謝，$N。願聖光與你同在。',0);
