INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (85,'zhTW','你不見了什麼？喔，我可沒拿什麼項鍊，因為我不是小偷！$B$B我可能知道是誰幹的……<奸笑>……不過我太餓了，想不起來。',0);
