INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (87,'zhTW','啊，你找到它了！謝謝，謝謝你，親愛的$N！$B$B請拿著這個。這是我丈夫的遺物，他總是說這個能帶來幸運。如果他最後一次作戰的時候沒有忘記帶上它就好了！*鳴鳴*',0);
