INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (89,'zhTW','做得好，$N。這些材料一到，我們就能好好地大幹一場了！現在就開工吧！',0);
