INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (91,'zhTW','湖畔鎮的法庭認可你對正義所做出的貢獻，$N。你執行王國的法律，維護了正義的尊嚴。',0);
