INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (92,'zhTW','太好了，$N。多好的材料呀！來，這就是你期待已久的赤脊山燉肉！',0);
