INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (122,'zhTW','多謝！這些應該夠我付清欠阿古斯的錢了吧……',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 123 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (123,'zhTW','嗯……我聽說過這個“收貨人”，不過不知道他到底在為誰幹活。謝謝你把這個日程表送來，它會幫助我們解開這個謎團。',0);
