INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (125,'zhTW','做得太好了，$N！我還以為我再也看不見這些工具了呢。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 126 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (126,'zhTW','再次感謝你的幫忙。暴風城的軍隊正忙著對付獸人，他們根本派不出人到赤脊山來維持治安和清剿豺狼人。',0);
