INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (134,'zhTW','感謝亡——呃，我是說，謝謝你，$N，你幹得太棒了！$B$B啊哈！太高興了！今晚真是太高興了！',0);
