INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (136,'zhTW','這隻置物箱慢慢地開啟。裡面似乎只有沙子和水。慢著！一隻小螃蟹衝了出來，寶藏的線索就在它的螯上！',0);
