INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (152,'zhTW','做得好，$N。你的戰鬥能力非常不錯。由於你的努力，西部荒野的海岸變的更安全了。',0);
