DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 158 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (158,'zhTW','你想要些殭屍汁？嗯……這東西味道很嗆——很少有人點它。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 159 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (159,'zhTW','真是太感謝你了，$N。你用你的愚蠢——我是說……你的善良——溫暖了一個老人的心！$B$B拿著，這代表我的感激之情。',0);
