INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (160,'zhTW','<艾爾羅看著信……>$B$B這信上寫的是什麼？看起來是種古老的語言……我看不懂。',0);
