INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (176,'zhTW','哈！幹得好！我還以為沒人能幹掉那個怪物呢！$B$B拿著這個，$N。謝謝你——這隻豺狼人給我帶來的麻煩足有黑石塔那麼大！',0);
