INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (181,'zhTW','觀星工具終於完成了！謝謝你，$N。現在我可以繼續我的研究了……',0);
