INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (182,'zhTW','啊！那些天殺的巨魔！$B$B<他深吸了幾口氣，似乎想平靜下來……>$B$B一夥巨魔趁著夜色溜了進來，把我的日記給偷走了！我就知道我那沒用的學……',0);
