DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 184 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (184,'zhTW','太感謝你了，$N。如同我所說的，這一帶已經不再適合老實人住了，不過當情況好轉的時候，我們就可以用這張地契來收回我們的土地。$B$B我沒什麼東西可以給你，但請收下這個。',0);
