INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (189,'zhTW','喔，太棒了，實在是太棒了。這一陣子情況至少會好一點點……$B$B<他的聲音變輕了，嘟囔著花費和報酬……>$B$B什麼？你怎麼還在這兒？報酬？噢，對……當然，拿著吧……絕對是只多不少的。',0);
