INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (195,'zhTW','現在你可以在家裡的壁爐上掛上一兩隻恐龍腦袋當戰利品啦！做得好，$N！',0);
