INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (198,'zhTW','這些地雷可以用來幫助我們抵抗庫爾森和他的部下的進攻。謝謝你將它們送過來，要是你還想找些別的工作的話，我想我可以找些事讓你做。對了，你應該不需要和那群地精打交道吧，嗯？',0);
