INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (309,'zhTW','啊，感謝聖光，炸藥終於運來了。不過你帶來的訊息也很讓人擔憂。黑鐵的支持者想要搶了些炸藥去實現他們邪惡的計劃。$B$B這個問題還是留給別人來考慮吧，我得趕快工作去了。',0);
