INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (310,'zhTW','你迅速把馬萊斯的熱麥酒混入到一大堆裝著雷霆啤酒的酒桶之中。',0);
