INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (311,'zhTW','幹得還不錯，$N！你沒有被那個看守發現吧？$B$B沒關係——非常感謝，如果你想要暢飲好酒的話，別忘了來找我們！',0);
