INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (312,'zhTW','你真是個好心的$C，$N！多虧了你的勇敢無畏，不然我整個冬天就都要忍飢挨餓了。',0);
