INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (315,'zhTW','太好了！讓我趕快把它發酵一下，我一定可以釀出一種口味獨特的酒來……',0);
