INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (317,'zhTW','以麥格尼鬍鬚的名義，你肯定獵殺了很多動物才收集到這些東西！謝謝你，$N。',0);
