INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (318,'zhTW','貝隆費茲想要一些我釀造的艾沃沙酒？嗯……沒問題。',0);
