INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (319,'zhTW','謝謝你，$N。我們再也不用聽著野獸的咆哮聲幹活，這真是太好了。',0);
