INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (325,'zhTW','你去得有點太久了，但我在你的眼中看見了從未有過的鬥志。$B$B看來你已經準備好了，摩本特·費爾一定會被徹底消滅的。',0);
