INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (328,'zhTW','開啟了這個保險箱之後，你發現這裡面裝著赫羅德的錢與其它的一些貴重物品。',0);
