INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (540,'zhTW','哦，你拿到它了！太棒了，我現在就開始研究《格里雷克之臂》！',0);
