INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (545,'zhTW','很好。現在我們可以去那片廢墟進行搜尋了，只要小心一點的話，應該就不會有危險。$B$B謝謝你，$N。',0);
