INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (549,'zhTW','很好，$C。按照這樣的形勢，在這片土地上到處流竄的辛迪加很快就能被消滅。',0);
