INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (554,'zhTW','這個羊皮紙上隱藏著一道精心設計的複雜法術。當然，我能解開它，不過需要點時間。$B$B時間對我而言是很寶貴的。',0);
