INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (556,'zhTW','這些足夠了。雖然看起來它的魔力已經消退了，不過用這種沒有活力的樣本來開始實驗對於魔導師來說是再好不過的了。$B$B謝謝你，$N。',0);
