DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 570 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (570,'zhTW','你對叢林的瞭解已經非常透徹了，$N。這些材料都很完美。森林之靈竟願意為部落的事業而犧牲如此優秀的野獸，我會感謝它們的。',0);
