INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (573,'zhTW','有了聖泉之水，魔法儀式便可以開始了。$B$B以自豪的心情戴上它吧，$N，以大酋長之名，為部落而戰！',0);
