INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (716,'zhTW','拿去吧，$N，趕快戴上這些東西。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 717 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (717,'zhTW','肯瑞託不用再為萊瑟羅峽谷裡的囚犯們擔憂了。我將把這個好訊息報告給我的主人。克拉蘇斯無疑會很高興的。',0);
