INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (719,'zhTW','你真是我的救星啊，$C。很高興看到有人能教訓一下這幫暗爐矮人，謝謝你的幫助。',0);
