INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (721,'zhTW','嗯？啊，對不起……咳咳我感覺很虛弱。你能靠近點嗎，$C？$B$B雷杜爾派你來的？他比我想象中的要快多啦……咳咳',0);
