INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (725,'zhTW','啊，是歷史學家卡尼克捎來的訊息。好極了。$B$B我願意為他效勞。$B$B<顧問貝爾格拉姆拆開信仔細地閱讀了起來。>',0);
