INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (726,'zhTW','$N，你在處理這件事情的時候行動非常迅速，我一直以來都希望國王陛下也能夠這麼對待這種問題。$B$B好吧，我知道該如何打敗暗爐矮人了。$B$B只要我們攻擊他們在荒蕪之地的軍事要塞——苦痛堡壘，就能對他們進行有效的壓制。',0);
