INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (975,'zhTW','給你，$N。記住，你必須帶著它。現在就去冬泉谷，看看你能找到些什麼吧。',0);
