INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (976,'zhTW','今天你表現得非常不錯，$C。德爾葛蘭送來的物資將被用於對付那些威脅著森林的黑暗勢力。$B$B請接受這些東西和我衷心的感謝。',0);
