INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (977,'zhTW','我等不及要給我的朋友展示這個機械雪人了！現在，稍等片刻，我這就把它們安上去……$B$B太完美了！',0);
