INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (979,'zhTW','你好！艾瑞拉斯讓你來找我的嗎？我正準備到那邊的山洞裡去看看呢，多個同伴也不錯！',0);
