INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (1104,'zhTW','好的！這個毒液會派上大用場！謝謝你，$N！$B$B現在我只要把它熬一下，用一些這個，加一些那個，再……見鬼！我的筆記本哪兒去了？',0);
