INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (1105,'zhTW','你拿到龜殼啦！謝謝你，$N！$B$B哇，這些殼比我想象中的還要硬！嘿嘿，要用它們來做燃料箱的話，肯定會弄壞一整箱的工具！',0);
