INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (1106,'zhTW','菲茲爾派你來的？你早說不就結了嘛！我當然會幫你。菲茲爾和他的兄弟是少數幾個不會想置我於死地的人！$B$B所以菲茲爾想要活塞？要堅固到足以承受他預計的任何壓力？以我對菲茲爾的瞭解，他的這部新車肯定會跟火箭一樣快。',0);
