INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (1110,'zhTW','哈，看看這個！在這些垃圾裡有不少好東西呢，我敢說這次肯定可以賺不少！$B$B還有……這兩片金屬中間夾著的是什麼？壓爛的耳朵？哦！我可不想跟那個駕駛員一樣！$B$B謝謝你，$N。這是你應得的報酬。此外我還有些忠告給你，當然是免費的……$B$B如果你有足夠強悍的話，你總能在事故中多多少少地獲利。',0);
