INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (1111,'zhTW','哦，對，確實有給克拉維爾的零件。我很高興你來到這裡，這些零件放在這裡有一些日子了，我都擔心它們快要生鏽了！',0);
