INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (1114,'zhTW','就是這些東西！我要的水棘齒和中繼器插梢！它們一定能派上大用場。謝謝你！',0);
