INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (1115,'zhTW','你想了解有關納茲·斯迪波爾的事？那個閃光平原的賽車手，是嗎？$B$B嗯，我也許能找到一些關於他的東西……但這並不容易，也不會很快。$B$B當然，也不會很便宜。',0);
