INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (1116,'zhTW','哦，不錯不錯，你找到幻夢之塵了！$B$B你覺得那個沼澤如何，$N？那裡可不是個度假的好去處，對吧？',0);
