INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (1118,'zhTW','我懂了。克拉維爾有一個很大的計劃。他夠殘忍，我喜歡！$B$B你需要一些東西，對嗎？……某些強大的東西……$B$B我不知道那些贊吉爾用來餵食他那些疆屍的藥劑是否有用……',0);
