INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (1119,'zhTW','太好了！菲茲巴布成功啦！下次見到他我一定要好好謝謝他。$B$B多謝你，$N。你做了一件了不起的事，我們一起來靠這東西賺大錢吧……',0);
