INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (1131,'zhTW','你打敗了鋼齒土狼，清除了千針石林中一個可怕的影響。$B$B希望你能從中領悟到一些東西，$N。',0);
