INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (1132,'zhTW','你好！是米奈希爾港的弗林特先生派你來的嗎？弗林特先生從來就不會看錯人的。如果是他派你來的，那麼我堅信你就是那個命中註定要在卡利姆多做出一番事業的$r。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 1133 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (1133,'zhTW','$N，你是來為聯盟提供幫助的嗎？我們歡迎這樣的幫助，儘管梣谷森林美景依舊，但它早已不是以前那片安寧祥和的森林了。',0);
