INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (1134,'zhTW','謝謝你，$N。殺戮那些並非獸人幫兇的可憐生物令我感到悲傷，但這是我的職責所在。$B$B我的朋友，也許你會為那些被你殺死的雙足飛龍而流淚，但你的盟友可以因此免受巨翼毒液的傷害，希望這可以讓你的心靈得到些許的慰藉。',0);
