INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (1135,'zhTW','啊，這些毒囊幾乎個個新鮮飽滿，$N。通常這些毒液只有在幼年或者雌性的雙足飛龍身上才能找到。我猜你一定在風巢幹掉了不少雙足飛龍！',0);
