INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (1136,'zhTW','$N，能打敗霜喉雪人就證明你有著過人的力量和機智。$B$B現在你已經去過了千針石林大峽谷和奧特蘭克山，將來你一定會走遍世界，因為這是一條屬於獵人的命運之路。',0);
