INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (1169,'zhTW','收集這些心臟和舌頭確實是件危險的事。我會深入研究這個秘密，找出襲擊我們以前家園的罪魁禍首。',0);
