INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (1170,'zhTW','你跟我說那些龍幹嘛？我不喜歡龍。我喜歡這兒，這兒沒有龍。',0);
