INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (2609,'zhTW','我在做什麼？我看起來像是在做什麼？我當然是在為你的伊提斯綜合症研究治療方法！現在別對我發火，$N！$B$B再等幾秒鐘。好了！把這個噴上，嗯，噴在你身上味道不錯，你會煥然一新的。',0);
