INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (2621,'zhTW','索爾近衛軍……我還清清楚楚地記得那可怕的一幕。$B$B<指揮官盧爾格搖了搖頭。>$B$B這個軍團經歷了可怕的遭遇。部落也因此失去了最好的一批士兵。',0);
