INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (2681,'zhTW','你成功了，$N！那些飽受折磨的可憐靈魂終於可以安息了。$B$B不過我們的工作還沒結束，$N。我們還有很多事要討論，很多事要做。',0);
