INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (2741,'zhTW','你將角鷹獸的蛋放入機器，隨後裡面傳來了一些奇怪的機械聲響和嘟嘟聲。$B$B似乎測蛋器正在為這顆蛋稱重、測量和包裝。真是快捷又完善的服務！',0);
