INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (2748,'zhTW','很好，$N。我會把這隻蛋送到達納蘇斯去，希望它可以在那裡孵化！$B$B這是我對你的小小謝意，請收下它。',0);
