INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (2749,'zhTW','你找到了一隻普通的蛋，$N？請把它交給我……我們只能往好的方面想了。$B$B我沒有多少錢，不過請收下你的報酬。如果你再去菲拉斯的話，別忘了幫我帶些蛋回來。',0);
