INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (2750,'zhTW','我有個壞訊息要告訴你，$N。這顆蛋實在是無法滿足要求，我可以幫你把它處理掉。$B$B不要灰心，我們總不可能把它們都孵出來。如果你要再去菲拉斯的話，就繼續幫我找些蛋回來吧。',0);
