INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (2751,'zhTW','沃姆什的血脈就要斷了，不過它的傳說還將繼續！$B$B你已經證明自己是個名副其實的鐵匠，$N。對鐵匠來說，最好的獎賞就是看到自己所造的武器和護甲沾上敵人的血！$B$B但願你所鑄造的胸甲都能在戰場上浸染你的敵人的鮮血！',0);
