INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (2756,'zhTW','$N，看來你不過是大酋長手下又一個容易自足的傢伙，太讓人失望了。$B$B我多麼希望能在戰場上光榮地死去，可是現在我卻得困在這裡，聽從索爾的命令去訓練新手！仔細看好了，孩子！',0);
