INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (2758,'zhTW','很好，$N！用心聽著！$B$B鍛造的手藝絕不是起源於這裡！<巨錘漢克指向他的鐵錘。>$B$B鍛造的手藝絕不是起源於這裡！<巨錘漢克指向他的鐵砧。>$B$B鍛造的手藝只能起源於這裡！<巨錘漢克指向自己的心。>$B$B現在你知道鍛造的起源了吧。',0);
