INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (2761,'zhTW','你的工作態度完美無缺，$N！你已經開始理解加爾文的採礦哲學了！拿著這個，從中儘可能地學習$B$B更多的東西吧。',0);
