INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (2762,'zhTW','她是個倔強的姑娘，不是嗎，$N？當然，我是說真銀。沒錯，加爾文在奧特蘭克的山區裡待了十多年才學到了這一點。拿著這個，從中學習你所能學到的一切！',0);
