INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (2935,'zhTW','啊，你想要枯木巨魔的新鮮蜘蛛毒液，對嗎？好吧，坐下……接下來我將要告訴你的東西可能會讓你不太舒服……',0);
