INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (3341,'zhTW','$N，一個巫妖的忠誠度是毋庸置疑的。讓他們知道這樣的忠誠只會給他們帶來毀滅。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 3361 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (3361,'zhTW','太好了，你找到我的東西了！你真是我的救星！這給你，這些報酬雖然不多，但是它們表達了我對你的謝意！謝謝你！',0);
