INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (3363,'zhTW','你將一些塞納里奧植物藥膏塗在了這株輕歌花上。它立即擺脫了剛才奄奄一息的狀態，重新變成了一棵活力十足的健康植物。',0);
