INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (3365,'zhTW','太棒了，$N！如果你知道我以前碰到過多少個忘記把杯子還給我的快遞，那你一定會大吃一驚的。杯子不是從樹上長出來的，',0);
