INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (3368,'zhTW','<索里奧斯抹乾了臉上的淚水。>$B$B以聖光的名義，他的遺願一定會實現。我發誓。',0);
