INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (3373,'zhTW','你把寶石放入精華之泉中。$B$B“感謝你，凡人，你已經——不……不，不可能！不！這個可惡的古神的墮落力量已經汙染了綠龍軍團的精華之泉的聖潔！不，不要，我感到自己的精華正在從我的身上剝離！痛苦！我感到一個永恆的夢魘已經控制了我……”$B$B“凡人，我求求你！去找綠龍族的一員來阻止這一切……幫幫我……我被拴在黑暗之中……永遠陷於痛苦……請不要再折磨我了……”',0);
