INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (3374,'zhTW','你已經做出了選擇，我們這就開始吧。你的選擇現在在我看來是正確的你將要採取的行動和所得到的結果將會影響我們是否繼續這件事情。',0);
