INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (3376,'zhTW','正義因你迅速的行動而得到了伸張，$N。讓我們用這一件事來警告那些企圖威脅我們家園的敵人吧。$B$B這是你應得的獎勵，希望它能在你的旅途中派上用場，年輕的$C。',0);
