INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (3380,'zhTW','嗯，沉沒的神廟，我可是親眼見過它的。也許你想要知道更多有關它的訊息？$B$B你看起來就是那種愛冒險的型別——我想，你也許會對我所知道的東西感興趣……',0);
