INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (3385,'zhTW','你對暗黑拍賣會進行了一次致命的打擊。他們的領袖在派更多人進入灼熱峽谷之前一定會考慮再三的。$B$B哦，我在這個商人的背袋裡沒找到什麼有用的東西，你可以隨便把它處理掉了。',0);
