INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (3402,'zhTW','考維克被幹掉了？真是讓人興奮的一天啊，$N！這些年來，這個惡棍一直都在從事暗黑拍賣會交易，欺壓全世界老實交易的辛苦商人。$B$B你理應為這個成就獲得一份獎勵！一份豐厚的獎勵！',0);
