INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (3451,'zhTW','這是我的標準型訊號槍，你發射之後要耐心等待一會兒——這把槍用不了太多次，我可能要花點時間才能到你那裡。發射訊號之後，你只需要盯著海面就可以了。',0);
