INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (3505,'zhTW','你開始瀏覽這本書，並翻到了一頁用黑色絲巾標出來的書頁。$B$B在你試著解譯書上文字的時候，你發現在其中一頁的底部畫著一張地圖。你迅速地檢視了一下眼前的景物，並很快意識到地上的水晶、石陣，甚至某些東西的位置都跟這張圖上所畫的東西十分相似。',0);
