INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (3507,'zhTW','哈哈！看看你自己，可憐的女人！我要向你吐口水！$B$B謝謝你，$N。我衷心地感謝你！今天是個好日子！$B$B要是我有權力的話，我就送你一個王國！但是，也許你會對這件東西感到滿意的。$B$B<貝爾戈洛姆低頭看著那曾經背叛過他的法師。>$B$B哈哈！愚蠢的血精靈，看看你自己吧……躺在這麻布袋中，身首異處！這就是背叛貝爾戈洛姆的下場！',0);
