INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (3785,'zhTW','幹得好，$N。當大德魯伊需要晨光麥時，我會把這些交給他的。同時，請收下這個作為塞納里奧議會對你的酬謝。$B$B我們對晨光麥的需求量非常大，如果你想要繼續幫助我們的話，那麼當你種植出更多的晨光麥之後就把它們交給我。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 3786 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (3786,'zhTW','幹得好，$N。當大德魯伊需要晨光麥時，我會把這些交給他的。同時，請收下這個作為塞納里奧議會對你的酬謝。$B$B我們對晨光麥的需求量非常大，如果你想要繼續幫助我們的話，那麼當你種植出更多的晨光麥之後就把它們交給我。',0);
