INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (3913,'zhTW','你用力推動墓碑，它往旁邊挪動了一點，露出了一個小凹槽。$B$B把林克的劍放入這個凹槽之後，你發現凹槽的形狀和劍的形狀正好吻合……',0);
