INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (3923,'zhTW','這是什麼？哦，一個主動式負載平衡器！你什麼地方搞來的？你是不是去過貧瘠之地的風險投資公司了？$B$B你一定很勇敢，或者很愚蠢。',0);
