INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (3924,'zhTW','你成功了！我馬上就研習這本說明書的內容，然後找出修復主動式負載平衡器的方法！我和棘齒城的斯布特瓦夫談過了——他感謝你的幫助，並想要對你進行獎勵。$B$B我也想感謝你，如果我能修好它的話，我會通知你的……',0);
