INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (3962,'zhTW','謝謝你，$N。$B$B我會把金色火焰帶回我的故鄉，在那裡它將被好好保護起來，永遠不會再落入邪惡勢力的手中。$B$B你為我做了那麼多，希望你能收下這個。如果沒有你的話，我至今還不知道自己是誰！',0);
