INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (4024,'zhTW','<塞勒斯從你的手中一把拿過烈焰精華。>$B$B就是它！$B$B拿著你的獎勵，然後走開。馬上從我眼前消失！',0);
