INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (4061,'zhTW','<塞朵拉把碎片放在她的面前。>$B$B<塞朵拉用一隻巨型放大鏡檢查著那些碎片。>$B$B很有趣。每塊碎片上面都刻著……一串字母。',0);
