INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (4062,'zhTW','<魯特維爾的臉變得煞白。>$B$B我……我知道這些東西代表著什麼……',0);
