INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (4104,'zhTW','幹得好，這裡是一些塞納里奧植物藥膏。如果你能在費伍德森林採礦過程中找到更多的硝酸鹽的話，記得一定要把它們交給我！這東西越多，我就能造成越多的藥膏來。',0);
