INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (4105,'zhTW','幹得好，$N——這種東西只要經過處理就可以幫助我們淨化費伍德森林。拿著這些塞納里奧植物藥膏，然後回到森林中去吧。奪回費伍德森林的任務迫在眉睫，$N！',0);
