INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (4120,'zhTW','從你的描述來看，那些生物都表現出一種歇斯底里的瘋狂……$B$B保持警惕，$N。你最好注意更多關於墮落的事情。對你的敵人要多一些瞭解。',0);
