INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (4121,'zhTW','你的英雄事蹟決不會被忽視，$N。你理應得到這些獎勵。另外，上面還有最後一個任務要交給你。',0);
