INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (4185,'zhTW','<伯瓦爾用手摸著下巴，好像陷入了沉思。>$B$B我尊重普瑞斯托女士的立場，我相信一定有辦法可以解決我們面臨的難題。',0);
