INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (4186,'zhTW','我覺得情況會更加糟糕……$B$B<所羅門鎮長看著你。>$B$B看來湖畔鎮的命運落在你的肩頭上了。$B$B<你注意到所羅門鎮長的眼睛溼潤了。他開始哭泣。>',0);
