INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (4201,'zhTW','啊，你成功了！現在我可以配製藥水並把它用到羅克諾特身上去了。他終於要成為我的愛情魔咒的犧牲品了！$B$B謝謝你，$N。你真是個愛情的鬥士！',0);
