INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (4221,'zhTW','你將兩份塞納里奧植物藥膏塗在了這株迎風花上。它立即擺脫了剛才奄奄一息的狀態，重新變成了一棵活力十足的健康植物。',0);
