INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (4242,'zhTW','顯然，他瘋了。$B$B<麥斯威爾難過地垂下了頭。>$B$B一個曾經是那麼光榮和高貴的戰士現在卻成了嘮嘮叨叨的傢伙。我猜想我們進了一個死衚衕……$B$B不管怎麼樣，我必須為你所做的努力而獎勵你，$N。',0);
