INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (4262,'zhTW','伊森迪奧斯？我的天啊……',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 4263 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (4263,'zhTW','哦，我的天啊！你確定伊森迪奧斯臨死之前說“拉格納羅斯”？$B$B<加琳達遞給你一件什麼東西，然後拍了拍你的手腕，隨即陷入了沉思。>',0);
