INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (4482,'zhTW','為了完成你現在所持的聖契，卡里爾花費的時間足夠讓你活上好幾輩子，$r。這都是為了什麼？為了讓他的信徒可以站在燃燒平原上，貶低他的研究，以滿足對魔法永無止境的追求和慾望……詛咒這該死的慾望$B$B我對你的無情和貪得無厭感到噁心，滾開！',0);
