INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (4483,'zhTW','其餘的聖契都遺失在這個世界上了，掉在你一輩子都不敢進入的地方，掉在你想都不敢想的地方。$B$B我要吸收這些材料的能量，剩下的殘渣就是你的了……',0);
