INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (4493,'zhTW','嗯，我知道是格拉希娜派你來的。你與這些小動物的作戰經驗是非常寶貴的，據我所知沒幾個人曾經對付過這類生物。至於格拉希娜所持的安戈洛環形山是異種蠍發源地的觀點……可能確實如此。安戈洛環形山是西邊的一個神秘而危險的叢林。也許我們可以在那裡搞清楚異種蠍的來龍去脈。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 4494 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (4494,'zhTW','嗯，我知道是格拉希娜派你來的。你與這些小動物的作戰經驗是非常寶貴的，據我所知沒幾個人曾經對付過這類生物。至於格拉希娜所持的安戈洛環形山是異種蠍發源地的觀點……可能確實如此。安戈洛環形山是西邊的一個神秘而危險的叢林。也許我們可以在那裡搞清楚異種蠍的來龍去脈。',0);
