INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (4729,'zhTW','你抓到它們的時機真是恰如其分，$N。如果再晚幾天的話，它們就不可能被馴服了！給我一分鐘，我就可以幫你把這隻小座狼馴化好。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 4730 AND `locale` = 'zhTW';
