INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (4904,'zhTW','謝謝你，$N。我知道她會回到我身邊的。她把你的英勇事蹟以及你幫她逃走的事情都告訴了我。這些東西原本屬於她的兄弟，現在她想讓你收下它們。',0);
