INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (5086,'zhTW','我要把這個和你在鍋中發現的東西進行比較，然後我們就能獲得更多資訊了。',0);
