INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (5087,'zhTW','<多諾瓦檢查木箱內的物品>$B$B我在想，熊怪是不是在喝下了這種東西之後就會變得更具攻擊性。它們看起來真的比以前更巨大……',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 5088 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (5088,'zhTW','為什麼會這樣？為什麼阿利卡拉要跟蹤凱恩·血蹄？瑪加薩不可能犯錯，她是我們最強大的薩滿。$B$B<莫特加搖了搖頭。>$B$B無論如何，你對部落所做出的貢獻不應被忽視——請從這些物品中挑選一件作為對你的幫助所給予的回報。',0);
