INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (5090,'zhTW','歡迎你來到瘟疫之地，英雄。這裡是艾澤拉斯最危險的地區之一，更糟糕的是，在我們北邊和東北邊的廣袤土地上，到處都潛伏著天災軍團的勢力。面對聯盟的召喚，你毅然趕來履行自己的職責，這讓我感到非常高興！$B$B如果你已經準備要上陣殺敵了，那麼，在瘟疫之地有足夠多的敵人，你想殺多少就殺多少。',0);
