INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (5092,'zhTW','任務完成了，$N！幹得好，幹得非常好。$B$B請允許我用暴風城提供的軍餉對你表示感謝。建議你用這些錢購入一些必需的物資，這將對你的下一個任務所有幫助……下一次，你將進入安多哈爾的廢墟！$B$B準備好了！時刻保持警惕！',0);
