INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (5121,'zhTW','非常感謝你，$N。我希望能不受干擾地繼續進行我的研究。請收下這個作為報酬。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 5122 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (5122,'zhTW','你找回勳章了！現在我可以離開這個教堂去繼續履行我的職責了。$B$B我的職責就是去殺死那個幫助腐蝕了我和許多兄弟姐妹的野獸，瑞文戴爾男爵！',0);
