INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (5125,'zhTW','$N，我快死了……但我的靈魂得到了拯救。我欠你的情是無法用言語來表達的。請拿著這個……繼續戰鬥下去吧，勇敢的$C！',0);
