INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (5441,'zhTW','很好，很好，也許他們下次偷懶之前會記起這次的教訓！感謝你的幫助！',0);
