INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (5461,'zhTW','我對這樣的東西是否存在曾經心存疑問。你找到了它，這給了我們一個非常珍貴的機會——我們決不能浪費這個機會。$B$B準備好，$N，接下來我要你做的事情就是深入通靈學院之中。',0);
