INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (5462,'zhTW','<萊尼德看著巫妖生前的遺物。>$B$B你的發現喚醒了我想要永遠埋藏的記憶。',0);
