INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (5464,'zhTW','既然靈魂已經附在了這件遺物上面，那麼這件遺物也已經與萊斯·霜語的肉身聯結了起來。',0);
