INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (5514,'zhTW','阿爾比頓說你會把東西送過來，那就拿出來吧！讓我把碎片和模具放在一起。$B$B阿爾比頓已經給它們附過魔法了？很好……否則的話，你就得再跑一趟冰風崗了。',0);
