INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (5641,'zhTW','你已經具備了成為一個偉大牧師的條件，$N。繼續加油！$B$B既然你已經做好了作戰的準備，那麼也許我們應該再教你一些東西了。',0);
