INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (5645,'zhTW','你終於來了，很好，$N。我們的種族是光榮而又強大的，關於這一點，你不僅要自己清晰地認識到這一點，還應該讓別人也有這樣的感覺。你準備好了嗎，$g小夥子:小姑娘？',0);
