INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (5669,'zhTW','很高興你來了，$N。我向聯盟控制下的各個地區派遣了許多使者，以確保你們能得到通知並返回暴風城。現在是你再次接受試煉的時候了，如果你準備好了，我們就開始吧。',0);
