INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (5672,'zhTW','透過向艾露恩和我們的同胞作出奉獻，你已經達到了一種並非所有人都能達到的境界。按照傳統，我將傳授給你更為強大的技能作為對你的回報，你接受嗎？',0);
