INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (5673,'zhTW','艾露恩護佑著你，讓你如此迅速地回到我們身邊。現在是你修行之旅中的一個重要時刻，我們對此都非常重視。當你從旅途的勞頓中恢復過來之後就告訴我一聲，然後我們就可以討論一下諸如你的試煉和未來之類的事情了。',0);
