INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (5713,'zhTW','這真是個好訊息，$C。我很高興得知阿娜莎還活著，謝謝你。請收下這個作為我對你英勇事蹟的獎勵。願艾露恩照耀你的道路。',0);
