INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (5803,'zhTW','沒錯，就是它！我……我又一次被你的英勇懾服了。我相信你一定願意為了戰勝黑暗而努力。$B$B現在該輪到我來盡點力了。我準備了一個特殊的溶劑讓我可以把聖甲蟲鑲在鑰匙的頭部，這樣它就能具有開啟通靈學院大門的力量。$B$B沒什麼難的……',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 5804 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (5804,'zhTW','沒錯，就是它！我……我又一次被你的機敏和勇敢折服了，我相信你一定願意為了獲得最終的勝利而努力。$B$B現在該輪到我來盡點力了。讓我把聖甲蟲鑲在鑰匙的頭部，這樣它就能具有開啟通靈學院大門的力量。$B$B沒什麼難的……',0);
