INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (5821,'zhTW','你知道，為了護衛基澤爾頓商隊而付錢給你這樣的$r並不怎麼讓我放心。如果我再高一點的話，我就能兼職打一份工，拿著我能拿動的最大號的槍坐在科多獸背上保護商隊……我會讓那些該死的半人馬知道誰才是真正的大爺！',0);
