DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 5893 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (5893,'zhTW','啊，你拿到它們了。幹得好，$N！這些補給品在那個黑暗的礦洞中放了太久，沾了不少灰塵，但是我們一定會好好利用它們的。$B$B謝謝你，$N。你為維持我們的戰鬥力做出了傑出的貢獻。',0);
