INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (5901,'zhTW','這些就足夠了，$N。謝謝你。$B$B如果你準備好了，我們就可以進行下一步了。',0);
