INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (5927,'zhTW','年輕的德魯伊，很高興你在此踏入正途。現在是你大步邁向一個更廣闊的世界的時候了。$B$B我們都向往著為自然效力。動物和植物是我們的朋友，也是我們力量的源泉。我們選擇為它們，也是為守護自然的平衡而奉獻自己的一生。作為進入這個世界的第一步，你首先要學習的是的熊之道，以及肉體和心靈所蘊含的力量。$B$B準備好了！',0);
