INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6131,'zhTW','我們在過去的事件中遭受了很多痛苦。謝謝你為幫助保護木喉部族所做的一切。',0);
