INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6132,'zhTW','我妹妹梅麗薩說過你會來的。多謝你把她從困境中解救出來，但她現在很可能又已經陷入新的困境了，這可真糟糕！',0);
