INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6134,'zhTW','它在那兒！看起來你身上還沾了一點。有點黏，是嗎？$B$B哦，給你添了那麼多麻煩，真的很謝謝你，$N。這東西值一大筆錢……如果我能讓半人馬們相信這是什麼！',0);
