INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6141,'zhTW','我聽說了有援軍要來的訊息，你就是來幫助我們的那個$r嗎？你是來幫助血色十字軍征討亡靈的嗎？$B$B如果是這樣，那麼請靠近些聽我說……',0);
