INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6142,'zhTW','真不錯，這正是巫醫教給我的治療頭痛的方法。他說，“麥拉斯，釣魚去。這會讓你感覺好得多。”$B$B哦，我已經覺得好多了，謝謝你！',0);
