INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6143,'zhTW','聽到納迦被擊敗的訊息固然很好，但我的心仍然覺得空蕩蕩的。在我的餘生中，我發誓要把他們全都殺掉。$B$B給你老兄，這是我許諾的獎賞。比起懲罰罪惡累累的納迦而帶來的滿足感，這點東西是微不足道的。',0);
