INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6144,'zhTW','大十字軍穩坐在血色十字軍堡壘中，與此同時，他的軍隊湧入你們的土地，褻瀆你們的紀念碑，屠殺你們的人民。$B$B黑暗女王已經命令我親自對付這條害蟲了，你會成為被遺忘者的先遣力量。',0);
