INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6162,'zhTW','你遵守了你的諾言。我的丈夫在戰鬥中犧牲——他以此為傲，但是我不能安心，除非我知道那個讓我孤獨一生的那頭野獸已經對它的所作所為付出了代價。$B$B再次謝謝你，$N。',0);
