INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6163,'zhTW','我想要知道……它求饒了沒有？它知道什麼是憐憫嗎？$B$B<納薩諾斯吐了一口唾沫。>$B$B我會把那個野獸的頭顱掛在我的牆上。$B$B你將成為我麾下諸多勇士的一員，$N。$B$B<納薩諾斯向你敬禮。>',0);
