INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6164,'zhTW','你成功了！天哪！我簡直都忘記這裡面記載了多少東西！$B$B真是榮耀的一天，$N！太驚人了！簡直太棒了！',0);
