INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6182,'zhTW','在收到幾起關於東瘟疫之地有被遺忘者異常活動的報告後，軍情七處派出了一些密探前去調查。調查的結果令人感到不安。',0);
