INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6185,'zhTW','拉戈爾。弗雷多。特伊恩。都……死了……$B$B<弗林特緊緊抓住徽記。>$B$B他們在哪裡？你有沒有發現關於這個混蛋的更多訊息，就是凋零者？',0);
