INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6186,'zhTW','被遺忘者的尖兵？女妖之王的勇士？$B$B<瓦里安·烏瑞恩國王顯得相當沮喪。>$B$B太荒謬了……',0);
