INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6187,'zhTW','這是個悲劇。我想……我認為我們的種族是被詛咒的，$N。我們損失了最偉大的戰士，我們最高貴的英雄，我們最富智慧的智者。$B$B我們很榮幸能夠擁有你，並且我向你保證，$N，不管納薩諾斯·瑪瑞斯如今在哪裡，他一定正在對著你微笑。',0);
