INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6261,'zhTW','這是要送到西部荒野去的木箱，對嗎？你以前去過西部荒野？如果你去過那裡的話，那就沒有問題了，我的朋友。我的這些訓練有素的獅鷲可以載著你直飛那裡！',0);
