INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6281,'zhTW','啊，軍需官路易斯的信？他需要更多的裝備，這一點我並不感到奇怪。哨兵嶺是如此的遙遠，它幾乎都要被暴風城遺忘了。$B$B好吧，謝謝你，$N。這是給你的旅費。',0);
