INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6282,'zhTW','太好了！再跟我說說你是如何讓那些邪惡的鷹身人四散逃竄的。血怒鷹身人已經遭受了重創！',0);
