INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6389,'zhTW','哈哈！謝謝你，$N！你做到了！我父親的靈魂可以安息了，我也能安安寧寧地過日子了。$B$B再次感謝你。要是有什麼我可以幫忙的地方，請儘管開口。',0);
