INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6390,'zhTW','謝謝你，$N。請拿著這枚硬幣吧。很抱歉我沒有更多的硬幣，但是你可以從摧毀血色十字軍的成就中獲得一些樂趣！',0);
