INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6391,'zhTW','啊，最新的布洛克優秀學生名單。我已經準備好了一批榮譽鋤，現在只需要學生的名字刻上去就行了……',0);
