INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6392,'zhTW','你帶來了鎬。棒極了！我將把它們分給我的優秀學員們。我敢肯定他們會很樂意在洛克莫丹的礦產開採中使用這些鎬的。$B$B謝謝你的幫助，$N。我欠你的人情，但是希望這些錢能補償你在旅途中的開銷。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 6393 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6393,'zhTW','我體內的水靈變得異常興奮。$N，我可以將你輝煌的勝利報告給海潮議會。',0);
