INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6394,'zhTW','好極了！非常感謝你，$N。這是我最喜歡的鎬！要是我的苦工能砍完這些樹，我們或許就能找到一個挖礦的好去處了！',0);
