INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6402,'zhTW','在開始之前，我要你首先集合一支軍隊。畢竟我們要面對的是一條龍！',0);
