INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6544,'zhTW','託雷克獲勝了！幹得好，$N。暗夜精靈是相當頑強的對手，雖然他們身材瘦小，但是力量強大，勇猛無比！我想這場戰役肯定很激烈……$B$B希望你在戰爭中留下了榮耀的傷痕！',0);
