INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6601,'zhTW','那只是單純龍與龍之間的對話，$N，熱空氣多過於實際有用的資訊。它們那些龍就只會採取豹而不實或者激進的行動。',0);
