INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6627,'zhTW','幹得好，$C。你已經認真讀過了我要求你學習的東西，你透過了我們的又一個測試。',0);
