INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6641,'zhTW','自從我到了這兒後，納迦進攻我們的事情就時常發生。聽到沃爾沙再也不能猖狂的訊息，讓我如釋重負！$B$B我們欠你一份人情，$N。',0);
