INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6662,'zhTW','可憐的蒙提。自從諾莫瑞根事件後，他就變了。那個孩子從來都從沒看過海，更不用說什麼海盜了。$B$B<尼普希嘆了口氣。>$B$B至少他還一直為我供貨。',0);
