INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6681,'zhTW','真精彩，小賊。$B$B你看起來似乎比較寒酸，但穿得還算得體。$B$B前面還有很長的旅程在等待著你去探索呢。你準備好迎接你在拉文霍德莊園的命運了嗎？$B$B與外面的警衛談談，他們會告訴你如何開始的。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 6701 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6701,'zhTW','哈哈，幹得好！繼續吧，其它的盜賊會對你刮目相看的。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 6721 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6721,'zhTW','不錯，是時候了，$C。',0);
