INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (6862,'zhTW','太棒了，$N。由於，嗯，伐木機中的自動計量等化器和鏈齒同步協調儀的天然的不穩定性，所以我只能保證它可以正常工作三天。三天之後麼……$B$B<斯菲萊克斯聳了聳肩膀。>',0);
