INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (7003,'zhTW','太棒了！讓我高興的不僅是你帶回了微縮殘渣，而且你壓根沒有缺胳膊少腿！這就是說，使用超級壓縮器沒有危險，太好了！$B$B感謝你對我的幫助，$N。你真是地精的朋友。請收下這個吧！',0);
