INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (7201,'zhTW','棒極了！我立刻就派信差把它們送到幽暗城去！$B$B這是我承諾會給你的報酬。拿著吧！',0);
