INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (7281,'zhTW','你的英雄事蹟不會被埋沒，$N。$B$B我必須抓緊時間來拯救他。我必須馬上聯絡希爾瓦娜斯！',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 7282 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (7282,'zhTW','你確定已經把他的屍體燒掉了，對嗎？',0);
