INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (7301,'zhTW','不可思議！你救出他們了，是不是？是不是？不過至少我們知道他們被關在哪裡了。',0);
