INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (7363,'zhTW','如果那些人類能夠安然接受他們病入膏肓的事實，並接受你的治療，那麼事情就會變得簡單很多。但是這樣也許就不太有趣了。繼續好好幹！我們終歸是要治癒他們的，方法並不重要。',0);
