INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (7368,'zhTW','現在他已經死了，你接下來所要做的就是把那些地雷給拆掉。這樣，我們就可以安全地透過那個區域，直到聯盟找到一個新的爆破專家。問題是，他們來得及嗎？',0);
