INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (7381,'zhTW','我倒要看看他們怎麼復活一具無頭的屍體！那些該死的蠢貨居然認為他們比拉格隆德聰明。$B$B<拉格隆德大笑著。>$B$B現在解散！哦，不要忘了拿你的符文。',0);
