INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (7382,'zhTW','這樣就沒問題了！顯然，那些野獸不可能復活一具無頭的屍體，是不是？$B$B你可以走了。哦，不要忘了拿著你的符文。',0);
