INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (7492,'zhTW','啊，很高興看到一個$C響應了我的召喚。我需要你的幫助，$N，你必須踏上一條危險的道路……$B$B一條通往厄運之槌的道路。',0);
