INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (7493,'zhTW','一個屠龍者，同時還是一個老練的制皮師？你讓我感到十分吃驚，英雄。$B$B請接受我將要教給你的東西。這種知識對於準備去摧毀所有黑龍軍團的你來說是十分有用的。$B$B我要教你如何使用黑龍公主奧妮克希亞的皮來製作一件披風，當你和你的隊友與黑石之王奈法利安作戰的時候，這件披風可以讓你們不至於被他那熾熱的火焰氣息燒成灰燼。',0);
