INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (7652,'zhTW','好吧，$g先生:小姐，我有個很好的提議。$B$B我這裡有一些帝國鎧甲的配方，我想要把它們賣掉，換些我用得到的東西。我所需要的只是一些瑟銀錠，你覺得怎麼樣？',0);
