INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (7786,'zhTW','即使在夢中，我也沒有想到會有這麼一天。$B$B看吧，凡人！$B$B見證比這個世界還要古老的力量！$B$B見證這個曾經面對過泰坦和神靈的王者！$B$B復甦吧，我的主人！擺脫你的枷鎖和束縛！復甦吧！',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 7787 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (7787,'zhTW','請你不要傷害我！拿著這把劍！拿著它！給德米提恩一個改過的機會！',0);
