INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (7788,'zhTW','銀翼哨兵部隊感謝你的貢獻，$C。我們和戰歌先遣騎的戰鬥遠未結束，但是你的勝利一定可以減緩他們建造戰爭機器的速度——即使只是減緩一小會兒。',0);
