INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (7797,'zhTW','傳送的理論就是將你炸得完全粉碎，透過空間裂縫將這些肢體的碎片傳送至別處，然後重新爆炸使你恢復原形。瞬間傳送！雖然這種方法也有不靈驗的時候，但是你是地精工程師！要是你將自己的性命看得很重的話，你是不會成為真正的地精工程師的！',0);
