INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (7881,'zhTW','感謝你，$N。你幹得真不錯。你的手藝絕對是頂級的！這裡是給你的暗月馬戲團獎券……希望你喜歡，$g先生:女士。',0);
