INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (7889,'zhTW','太棒了！這些東西非常合適！它們不太重，但是也不太輕，正好用來幫我來強化肌肉！$B$B非常感謝你，$N。這是你的暗月馬戲團獎券！',0);
