INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (7890,'zhTW','你把石頭帶來了！嗯，非常重！我已經可以感到我的肌肉在膨脹了。感謝你，$N！$B$B拿著，拿著這些獎券，不要在這裡吃太多的甜食。像你這樣強大的$C需要一直保持自己的身材！',0);
