INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (7891,'zhTW','太好了！這些正是我所需要的！多麼迷人的顏色啊，而且它們讓我的臂膀顯得如此強大！太完美了！$B$B給你，$N。這是你的獎券——希望你喜歡！',0);
