INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (7892,'zhTW','啊，太棒了！這柄鐵錘的頭很大。我打賭我可以用它敲碎掉任何東西。我只希望砸東西的時候它自己不要碎掉！$B$B這裡是你的獎券，$N。盡情享受在馬戲團的時光吧！',0);
