INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8048,'zhTW','警覺、榮譽、忠誠、勇敢……你擁有所有的優點，你的烙印也應如此。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 8049 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8049,'zhTW','$N，你要堅持不懈地奮力戰鬥。奪魂者會試圖汲取你求生的意志。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 8050 AND `locale` = 'zhTW';
