INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8109,'zhTW','剝去他們屍體上的鮮肉。看著黑暗的力量吞噬哈卡，從他們的恐懼中汲取力量，$C。讓科讚的玷汙再次強化……',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 8110 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8110,'zhTW','看到這些海藻了嗎？它們產自南海。我們往其中新增了一點魔精和魔法，它就成為一件非常有用的飾品。$B$B你是個德魯伊，這對你來說相當容易。把它戴在你的脖子上，想象一下大自然、松鼠或是所有你們會喜歡的東西。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 8111 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8111,'zhTW','看到這些海藻了嗎？它們產自南海。我們往其中新增了一點魔精和魔法，它就成為一件非常有用的飾品。$B$B你是個德魯伊，這對你來說相當容易。把它戴在你的脖子上，想象一下大自然、松鼠或是所有你們會喜歡的東西。',0);
