INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8113,'zhTW','$N，旅途愉快。繼續取哈卡和他的爪牙的性命吧。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 8114 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8114,'zhTW','做得好，$N！一個激動的斥候已經帶來了你成功的訊息。我們阿拉索聯軍上下都為你感到歡欣鼓舞！$B$B你已經漸漸變成這個軍團的英雄，今天你的事蹟又再一次證明了你的價值。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 8115 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8115,'zhTW','你成功了！你佔據了所有基地！做得好，$N！$B$B以前有人曾懷疑你能否順利完成，但是我就知道你會成功。感謝你，整個阿拉索聯軍向你表示致敬，而被遺忘者的汙染者每次提到你的名字，必定感到膽戰心驚！',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 8116 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8116,'zhTW','看看吧，$N。巫毒的力量更加強大了，不是嗎？讓原始的力量流遍你吧。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 8117 AND `locale` = 'zhTW';
