DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 8118 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8118,'zhTW','看看吧，$N。巫毒的力量更加強大了，不是嗎？讓原始的力量流遍你吧。',0);
