INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8181,'zhTW','這麼說，你已經跟那個老矮人詹斯·鐵靴談過話，知道丟失的摩沙魯石板的秘密了？那個愛管閒事的勘察員……$B$B沒關係。要挽救世界，現在已經太晚了。哈卡已經重獲新生，他的力量還在繼續增長中……他就在古老的巨魔王國祖爾格拉布！他來了！他將再次使世界籠罩在血腥和恐怖之中！$B$B謝謝你，$N。在你的幫助下，奪魂者又回來了！',0);
