INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8182,'zhTW','是勘察員鐵靴派你來的吧？他很聰明，派你來找我更是明智之舉——因為我和贊達拉巨魔知道如何打敗奪魂者。$B$B跟島上的巨魔談談，留意他們的話。準備作戰吧，$N，你要踏上的將是灑滿鮮血的道路。',0);
