INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8233,'zhTW','歡迎！歡迎！坐吧，$N，我們簡單談談。$B$B你知道，$N，我最近弄丟了一件心愛之物坦率地說，我願意不惜一切代價都要將它找回來。別擔心，我有東西送你的！是的，很不錯的東西。$B$B嗯，$N……你準備好冒險了嗎？',0);
