INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8272,'zhTW','感覺如何$N？摧毀你的敵人，看著他們的防衛線瓦解感覺如何？感覺很好，不是嗎？$B$B你應該為此次英勇行動感到光榮，士兵。',0);
