INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8282,'zhTW','太好了！你找回我的揹包了。所有的稀有材料都在這裡！我欠你很大一個人情。',0);
