INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8283,'zhTW','太棒了！死亡彎鉤一死，我們就能利用南部山脈的地勢，智取異種蟲巢。感謝你為此做出的努力。',0);
