INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8284,'zhTW','就和我懷疑的一樣。我可以解譯出石板上的所有文字，但是這些文字之間沒有任何邏輯關係或者含義。現在還不知道暮光之錘究竟用了什麼樣的密碼來掩蓋這些文字的含義……我們必須找到一些更加了解這方面資訊的人。',0);
