INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8285,'zhTW','看來你對我以前所屬的組織十分熟悉，你一定是塞納里奧議會派來的。$B$B你想要找到對抗暮光之錘的資訊？過來，也許我們可以互幫互助。',0);
