INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8287,'zhTW','這確實是非常有趣的資訊，$N。它說明了暮光之錘出現在希利蘇斯的部分原因，無疑這將幫助我們更好地和他們進行戰鬥。你的努力將獲得豐厚的回報，$C。',0);
