INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8297,'zhTW','你拿到資源了！幹得好！我會把這些資源送到我們的軍需官那裡，然後讓他迅速把它們配置給我們的軍隊。$B$B謝謝你，$N。事實上，不斷地完成這樣的任務將是獲得最終勝利的關鍵要素。',0);
