INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8298,'zhTW','啊，你搶到了更多的資源木箱！沒有資源補給的聯盟肯定會一敗塗地的！$B$B感謝你，$N。你的努力已經為我們所知，並且也為瓦里瑪薩斯所知。',0);
