INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8304,'zhTW','<指揮官瑪爾利斯低頭沉思。>$B$B不管她是生是死，我一定要做對的事。一定要找到她。唉，我因職責在身不能離開這個前哨基地。你能再幫我一次嗎，$N？',0);
