INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8305,'zhTW','你可以感覺到這顆水晶的周圍散發出巨大的悲傷。這股力量非常強大，你幾乎以為自己會因悲傷而死在這裡了。',0);
