INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8306,'zhTW','<指揮官瑪爾利斯抱住他的胸前。>$B$B克蘇恩？這到底是什麼意思？什麼是克蘇恩？這個魔鬼怎麼會把我可愛的納塔莉亞變成你們所說的怪物？',0);
