INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8308,'zhTW','嗯，這解釋了很多事。如果你找到去安其拉的路，注意一下老布萊恩。我怕他沒有猴子會很無力。',0);
