INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8309,'zhTW','我不能理解這些雕文。我從沒看過像這樣的東西！我希望法蘭克爾的研究可以讓這片混亂有些頭緒。',0);
