INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8313,'zhTW','讓我們來看看……$B$B這看起來夠簡單了。他們有些藥草有自己的名稱，不過那都可以簡單理解。來，讓我證明給你看！',0);
