INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8314,'zhTW','矮人無法解讀雕文的原因是因為根本就沒有東西可以解讀。柱體變動的外層一定要和內部水晶的印記密切配合才能傳送出訊息。聰明……$B$B我們雖然可以翻譯出這些資料，但首先一定要解開密碼。在柱體表面只有一條線索——假設印記有正確地轉變——而且它看起來很恐怖。',0);
