INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8316,'zhTW','伴隨著無法形容的恐懼，戰爭來臨了，$N。你已經做了你該做的事情，應該受到獎勵。$B$B這……這預言會成真嗎……$B$B<地質學家拉克斯班臉色變得蒼白。>$B$B我們也許沒有未來可言了。$B$B這些物資對你來說應該很有用。',0);
