INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8317,'zhTW','太棒了！你是個救命恩人。這些餃子真棒。沒想過暮光之錘的東西可以做出這麼好的味道。',0);
