INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8320,'zhTW','這是個執行的非常出色的任務，$N。殺死暮光地領主對他們的教派造成了很大的損失。希望他們的計劃因此緩慢下來……',0);
