INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8321,'zhTW','你成功了！維拉爾被殺了！這隻能算是暮光之錘在希利蘇斯的潰敗。雖然一定還有更多成員在四處搗亂，不過你今天給他們的教訓也夠厲害了。',0);
