INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8323,'zhTW','太好了！我會盡快把這些檔案儘快解碼。如果我發現任何有趣的東西，我會找到方法給你訊息的。',0);
