INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8362,'zhTW','幹得好！聖殿騎士的數量又減少了。$B$B給你，$N。希望這些東西對你有用。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 8363 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8363,'zhTW','太好了，$N！擊敗那些公爵將使得暮光之錘陷入一段時間的混亂。按照我的承諾，這是你應得的獎勵。這是我和胡姆能夠找到的比較好的東西。',0);
