INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8368,'zhTW','棒極了！你在戰歌峽谷保衛戰中表現很出色！願你的英雄事蹟在我們的土地上流傳開來。',0);
