INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8371,'zhTW','你沒有讓我失望，$N！你所學到的東西已經超越了獎章和表揚所能達到的範疇，它只有透過經驗積累和在戰場上的磨練才可以獲得。$B$B你幹得很好，$C。你是聯盟真正的英雄！',0);
