INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8416,'zhTW','你成功地完成了我交給你的任務，$N。$B$B你贏得了我的信任。或許現在我可以告訴你更多計劃的詳細資訊了。',0);
