INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8446,'zhTW','我必須將汙染從這東西上清除。這或許對翡翠夢境的研究工作有所幫助。把它給我。',0);
