INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8538,'zhTW','你為我們完成了一項偉大的任務，$N。你消除了對我們而言相當嚴重的威脅。在些表達我深深的謝意。',0);
