INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8571,'zhTW','太棒了！我剛剛發現了帳篷上的一條裂縫，正需要用這些護甲片中的一塊來修補它！$B$B非常感謝你，$N。它們可以幫我們節省大量的修補費用。這裡是你的獎券——祝你玩得愉快！',0);
