INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8620,'zhTW','太棒了！真不敢相信你真的突破了那個難題！你是機器嗎？換作是我，我可能會讓整個世界爆炸。$B$B告訴你，$g先生:女士。英勇的行為一定會得到獎勵的。',0);
