INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8624,'zhTW','太好了……蟲的皮膚會是很棒的保護層。和我們在路上摧毀的其拉材料結合，這會是個令人畏懼的護甲。願它協助你面對裡面難以言喻的恐怖。',0);
