INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8625,'zhTW','我用你帶來的材料和其拉蟲人的鱗片製成了這套肩鎧，凡人。希望它們能給你適時的保護也能讓我們的敵人嚐到恐懼的滋味。',0);
