INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8792,'zhTW','（獸人語）你好，$C！很高興看到這麼多像你$N一樣的部落成員，伸出援手為安其拉之戰打好基礎。這樣的努力一定會讓我們勝過異種和他們藏在安其拉里面的邪惡主人。$B$B既然你在這裡，記得去和不同的收集者談談並提供你的協助，收集你能取得的材料。',0);
