INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8957,'zhTW','就因為這個勳章，這個詛咒才會降臨到我們身上。瓦薩拉克領主顯然知道如何掌握仇恨。$B$B我們會盡力找到剩下的碎塊——希望是在我面臨最終的死期之前。不過在那之前，讓我們先來看看你的獎勵。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 8958 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (8958,'zhTW','我真不敢相信我們的日子就因為這個愚蠢的勳章而綁死了！你確定安希恩有提到佈德利嗎？$B$B嗯，你完成了你的工作，讓我們來看看你的獎勵吧。',0);
