INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9015,'zhTW','你取回了部分的勳章了嗎，$N？',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 9016 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9016,'zhTW','就因為這個勳章，這個詛咒才會降臨到我們身上。瓦薩拉克領主顯然知道如何掌握仇恨。$B$B我們會盡力找到剩下的碎塊——希望是在我面臨最終的死期之前。不過在那之前，讓我們先來看看你的獎勵。',0);
