INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9119,'zhTW','看看你的四周，東西都亂七八糟。我們在西部聖殿有嚴重的運作不良。讓我們盡力阻止情況變得更糟。',0);
