INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9120,'zhTW','我一生中從不期望見到這個東西……$B$B<蒙託神父好像開始流口水。>$B$B喔太好了，你會得到獎勵的，親愛的$g小男孩:小女孩。你會得到豐厚的獎勵。拿去。快！',0);
