INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9174,'zhTW','你為我們的死報了仇並解放了我們在海之平衡手上的靈魂。我們終於可以安息了。',0);
