INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9180,'zhTW','<希爾瓦娜斯從你手中拿走項鍊。>$B$B這怎麼可能！這麼久以來，我以為我永遠失去它了。$B$B<一陣靜默後，女王開始重新注意到周圍的情況，鎮定了下來。>$B$B你以為這樣就能取悅我嗎？你以為我還會懷念那段成為被遺忘者女王之前的時光嗎？就跟你這個人一樣，這東西對我來說完全沒有意義，而艾蘭里亞·風行者也只是一段逝去的回憶罷了！$B$B<她把護符丟到地上去。>$B$B你現在可以立刻消失在我眼前，$C。',0);
