INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9185,'zhTW','毛皮護甲片的用處比你想象中還多，$N。他不只可以給予防具更多的護甲，他也可以拿來當做茶壺墊！',0);
