INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9202,'zhTW','你知道在前線作戰的士兵給這種藥水取了什麼外號嗎？裝在瓶子裡的牧師……$B$B<馬隊管理者布魯斯開始唱歌。>“我是你瓶中的牧師……寶貝……只要你需要我就幫你治療……”',0);
