INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9212,'zhTW','你真是位$g英雄:女英雄，$N。能從那些巨魔手中平安救回她。我想我們也必須發動攻擊清空地下墓穴。$B$B你今天做了一件偉大的事，$B$B我應該要獎勵你。從這些東西里面選一個吧。',0);
