INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9255,'zhTW','這份資料……令人震驚。如果它們是正確的，那麼就表示死亡之痕的傷害是無法補救了。$B$B我會立刻通知大魔導師，這樣就有更多的理由要讓我們的種族逃離這個世界並瞭解在外域中的真正命運。',0);
