INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9259,'zhTW','讓我們為這些陣亡的朋友哀悼，$N。$B$B<血帆背叛者對你咧嘴笑了笑，使了個眼色。>$B$B當一個背叛者是一回事，殺死你自己的兄弟……那才是真正可鄙的事！',0);
