DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 9317 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9317,'zhTW','謝謝你，$N。這是你的聖化磨刀石。謹慎地使用它們。',0);
