INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9319,'zhTW','你的本質和你所找到的火焰能量共鳴著，$N。你找到的火焰相當強大，只需要正確地處理，就能增強它的力量……$B$B<老者對著空氣中低語，然後拿出一個發光的瓶子。>$B$B啊！好了。不管你往何處去，願它照亮你的道路。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 9320 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9320,'zhTW','拿去吧，$N。在那裡要小心。我們的數量沒有那麼大，不能容許太多人陣亡。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 9321 AND `locale` = 'zhTW';
