INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9338,'zhTW','你為我們帶來榮耀，$N。有你持續的努力我們會克服所有障礙的。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 9339 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9339,'zhTW','你今天已證明了自己的能力，$N。$B$B我沒有什麼東西可給你，我只有這個王冠是個適合勝利者的禮物。願它照亮你的路。',0);
