INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9341,'zhTW','收下這件外袍並驕傲地穿上它。或許你的行為能激勵其它人也加入我們對抗天災軍團的行列。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 9342 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9342,'zhTW','做得好，$N。清空道路是一件重要的成就，但那不是對付這威脅的第一步。$B$B那些蟲體不久就會重新回來，所以我需要空出一些軍力來阻撓他們。收下這些錢做為你努力的獎勵這是你應得的。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 9343 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9343,'zhTW','收下這件外袍並驕傲地穿上它。或許你的行為能激勵其它人也加入我們對抗天災軍團的行列。',0);
