INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9352,'zhTW','暗夜精靈？這裡？那些小人！$B$B你覺得他們和我的聖殿運作不良有關嗎？如果你有任何訊息，最好立即送給艾爾杜上尉。',0);
