INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9354,'zhTW','<哈姆菲對你點點頭並伸出他的手。>$B$B要花很大的工夫才能完成我腦筋裡想的東西。謝謝你為我帶來這些材料，$N，這些錢是給你的獎勵。',0);
