INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9355,'zhTW','做得好，$N。不過我們先不要高興的太早。我確定我們還沒完全消滅那些蟲仔。如果你又在這附近看到他們竄頭竄腦，洛薩之子會準備好殺死他們的！',0);
