INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9362,'zhTW','我必須說，這個貝殼有一種奇怪的光環。看來要獎勵你取得它的一部分報酬就是派你去測試它的魔法潛力……',0);
