INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9365,'zhTW','你今天已證明了自己的能力，$N。$B$B我沒有什麼東西可給你，我只有這個王冠是個適合勝利者的禮物。願它照亮你的路。',0);
