INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9367,'zhTW','太好了！如果那些營火真的如你們所說的那樣熾熱的燃燒著，看來我們今年指派的火焰管理器都很盡責。謝謝你幫我去調查來，收下這個做為我一點小意思。',0);
