INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9369,'zhTW','真令人遺憾，那些生物必須死亡我們才能生存——不分青紅皂白的殺戮不是我們德萊尼人的作風。不過，你所收集的血清會補充我們的治療水晶，所以他們不會死得毫無價值。',0);
