INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9370,'zhTW','那會讓那些神聖的狂熱者不再幹擾別人的事。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 9371 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9371,'zhTW','喔，謝天謝地你來了。我們還有很多事要做。',0);
