INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9483,'zhTW','你知道，或許我們可以成為朋友。跟我來——我們可不想和別人分享這個東西，對吧？',0);
