INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9484,'zhTW','能抵擋龍鷹無數的爪子和噬咬就顯示了你的韌性。你有力量學習更多東西嗎？',0);
