INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9530,'zhTW','我一定要警告你，我接下來要叫你做的事很危險。如果你決定不幫我，我也不會看輕你的，$N。',0);
