INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9542,'zhTW','當你閱讀圖騰時，你的嘴巴構成了一個字——瓦克。你知道這代表了正義。',0);
