INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9612,'zhTW','做得好，$N。做的非常好！你成為了一個特別的德萊尼——在你同年的人當中脫穎而出。收下這個做為獎勵！',0);
