INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9613,'zhTW','你怎麼會發現這個？這把劍上有著我真正主人的徽印。$B$B非常好，我會幫你。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 9614 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9614,'zhTW','這把劍已經重鑄了，$N。$B$B這真是奇特的經驗。我從沒聽過一個武器……抱怨……這麼多。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 9615 AND `locale` = 'zhTW';
