INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9616,'zhTW','感謝沃洛斯！你把這個帶來給我真是太好了，$N。這些血精靈四處遊蕩就是為了……嗯，血。要立刻通知維倫！收下這個做為獎勵。',0);
