DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 9624 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9624,'zhTW','你找的很辛苦嗎？我都要花上越來越多的時間才能回來。$B$B我很快就要全部停工了，因為我沒有空餘時間！謝謝你幫我收集沙梨，$N。這讓我在雷象產期結束前還能做最後幾個電信。',0);
