INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9626,'zhTW','<索爾開始讀這封信。>$B$B希爾瓦娜斯是個固執的人。所以她派了銀月城的一個勇士……這能改變什麼？',0);
