INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9631,'zhTW','奧圖魯斯想讓整隻龍死而復生？用想的就知道這不是件簡單的事。$B$B讓我們討論一下該如何為彼此提供協助，$N。',0);
