INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9634,'zhTW','做得好，$N。掠食者數量需要再觀察一陣子，但我們有了個好的開始。',0);
