INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9635,'zhTW','很好！如果我們再有魔鐵外殼，魔鐵螺絲，精密奧金轉換器和一些源生生命就好。然後我們就能真的做點東西了！$B$B好好好，你值得這個獎勵，$N。玩的愉快！',0);
