INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9636,'zhTW','閃亮！而且真的，哪個工程師會覺得自己有足夠的備用零件呢？喔，或許我可以賣掉一些多餘的零件來買一些提古勒和弗洛爾的草莓冰淇淋？！我愛死草莓了！你覺得他們這附近有賣嗎？$B$B好好好，我想你贏得了這個，$N。玩的愉快！',0);
