INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9641,'zhTW','做得好。這些會為另一批增強水晶提供純原材料。$B$B從我製作的三種水晶中選擇一種吧，我發現它們對追蹤不同的獵物各有所長。',0);
