INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9662,'zhTW','你辦到了……我的靈魂……我真正的靈魂再次自由了。我永遠都欠你一份人情，$N。',0);
