DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 9817 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9817,'zhTW','我打賭血鱗納迦下次要攻擊遠征隊斥候時會三思而行。拿著這個做為獎勵，$N。這是你應得的。',0);
