INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9818,'zhTW','<戈達烏似乎在對你點頭。>$B$B坐下。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 9819 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9819,'zhTW','<戈達烏肯定地點點頭。>$B$B很好。靈魂安息了。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 9820 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9820,'zhTW','做得好，$N。不過這些食人魔距離我們前哨這麼近，著實讓我擔心。看來他們從北邊的山上往下滲入已經有一段時間了。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 9821 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9821,'zhTW','<戈達烏把咀嚼過的石塊吐出來，在你面前形成了一個碎石堆。>$B$B毒藥。這些石頭不是納格蘭的。這些石頭是毒藥做的。你要摧毀毒藥石塊。你要找到侵佔者古羅克。',0);
