INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9840,'zhTW','<卡爾侖帶著不確定的眼神看著你。>$B$B我完全不知道你所說的紫羅蘭之眼。我只是個鐵匠而已。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 9841 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9841,'zhTW','我也是這樣想。我已經可以聽出它的差別了。我終於能回去工作，多虧了你。如果你需要什麼商業補給，別忘了加巴林卡！',0);
