INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9842,'zhTW','這些應該足夠我用上一陣子了！我想其它人已經開始注意了。已經有些人出價要買我的劍了。販賣它們可以提供我比平時更好的生意。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 9843 AND `locale` = 'zhTW';
