INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9844,'zhTW','你辦到了！讀數恢復正常了！$B$B我們一定要把這個訊息告訴賽卓克。他一定會對你的成就很驚訝的。',0);
