INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9850,'zhTW','令人印象深刻。非常了不起。$B$B你有潛力，孩子。現在我要給你機會嚐嚐真正的樂趣！',0);
