INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9857,'zhTW','那是個好故事……咳咳……你如何獵捕那些塔布羊的故事，$C。但我想你可以做的更好。我想好了別的事要給你做。',0);
