INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9860,'zhTW','奧圖魯斯告訴我所有發生的事了，$N。不過，這並不是結束。卡拉贊仍對外人封閉，燃燒軍團在我們沒有能力的時候重新攻擊也是遲早的事。$B$B除非你接受命運給你的責任。$B$B<賽卓克伸出張開的手心遞給你一個鑲著單顆紫羅蘭水晶的戒指。>$B$B你說怎麼樣，$N？',0);
