INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9905,'zhTW','<普爾魯認可地點點頭。>$B$B普爾魯感謝你的幫忙。普爾魯終於可以放下心來。他不會再突如其來的被攻擊了。',0);
