INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9907,'zhTW','如果這樣依然無法讓他們就此罷休，那就沒有別的辦法了。你踐行了瑪格漢的正義，$N。對於正義，瑪格漢會給予大大的獎勵。',0);
