INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9911,'zhTW','你確定那是真的嗎？我是說，我知道泥沼有大型野生生物，但是真的大型生物，而且是超大型的昆蟲。$B$B想想看，孢子人的確提過一個關於可怕蟲體的故事，在泥沼領主入侵之前這個大蟲令他們恐懼不已$B$B。$B$B如果故事是真的呢？喔，天啊。我最好妥善保管它。遠征隊會想知道這件事的。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 9912 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9912,'zhTW','歡迎來到塞納里奧庇護所，$N。我希望你是來協助我們的任務。我們有很多工作要做。',0);
