INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9914,'zhTW','我從未對你有過一絲一毫的懷疑，$N。它們大部分看起來是很好的樣本，只是有一點髒和刮痕。但我還是認可它們的價值。$B$B我希望我們未來可以繼續合作。',0);
