INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9917,'zhTW','<彬圖克讀著計劃書。>$B$B以聖光之名！他們的字跡糟透了。就我所能收集到的資訊，他們不是在計劃著“吃掉藍皮膚的傢伙並奪走他們的村子”就是在烤藍莓派。這兩種都有可能。我們一定要查個水落石出！',0);
