INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9919,'zhTW','你幫忙保護了下一代的孢子人，$r。我們只能以歡迎你來作客做為答謝。留下來一會兒，見見其它的孢子人。他們會有很多問題問你，我希望你不介意。',0);
