INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9920,'zhTW','<姆摩爾看起來很困惑。>$B$B所以，有一支新的食人魔部族正將石拳越來越往南推進。這真是相當麻煩。我們一定要先解決這個離家最近的情況……',0);
