INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9957,'zhTW','我很高興塞納里奧庇護所派你來。這片樹林的德魯伊都被殺死了！只有我和另一個人還活著，而他也瘋了。$B$B我不知道發生了什麼事，但我想追根究底。不管是什麼原因，它來得很快且不合常理。$B$B你會幫我嗎？',0);
