INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9963,'zhTW','我怎麼知道你說的是真的呢，陌生人？$B$B<鳥人仔細地注視著你，露出你認為應該行的通的扭曲笑容。>$B$B我該看看水晶球來占卜你的意圖嗎？恐怕事情不是這樣的。',0);
