INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9966,'zhTW','他不會是最後一個打擾我們的食人魔了，我確定，但我要他們退回納格蘭的命令起不了作用。我擔心我的聲音對人民而言已經沒有份量了。$B$B不過那是我的問題，與你無關。你已照著我的要求做，所以該我實現我們的協議了。',0);
