INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9970,'zhTW','你讓巨魔流了不少汗，小鬼！這次有些特別不一樣的東西——不要一次把它們全用完。$B$B你準備好下一場挑戰了嗎？',0);
