INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9971,'zhTW','所以，我是對的。那是一具破碎者的屍體嗎？你確定他旁邊地上有個奇怪的物體？$B$B真是不合理。那個破碎者去那裡做什麼？他擁有的是什麼東西？$B$B就是那個東西導致他遇害的嗎？',0);
