INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9972,'zhTW','小鬼！小鬼就是這樣！下一場比賽很重要！是勇士賽！$B$B好，沉著以對。我們不想讓食人魔知道我們任何的動靜。',0);
