INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9980,'zhTW','我必須承認，$N，我又驚又喜。當薩德爾告訴我迪羅姆被拘禁在沙拉斯鴉巢時，我開始擔心我們是否會永遠失去他的音訊。$B$B這是我第一次這麼高興我是錯的。$B$B你可以相信我們此後會對鴉人活動密切觀察。',0);
