INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9988,'zhTW','這些東西會很有用，雖然我知道那些人很快會開始抱怨缺少變化。聖光禁止它們應該看起來都一樣！$B$B<羅斯勒斯假裝害怕的喘著氣。>$B$B喔，不，我們不能這樣！',0);
