INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9989,'zhTW','這些東西會很有用。你收集的愈多，當我試著與鴉人靈魂接觸時就會有越多人幫助我。謝謝你的幫忙，$N。',0);
