INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9990,'zhTW','虛靈組織？送到圖雷姆的物品？特殊的工程學零件？還有一個血精靈準備要將最後一箱送到火翼崗哨？$B$B這些話是什麼意思？！這些跟塞納里奧樹林裡的那些德魯伊有什麼關係？$B$B我想我們該看看箱子裡的東西。',0);
