INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (9998,'zhTW','<高等精靈點點頭。>$B$B這是個好的開始，但波爾泰姆派你來是對的。我有個新發現或許能解釋邪獸人出現在這的原因。',0);
