INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10000,'zhTW','恐怕阻止邪獸人將不只是干擾他們的工人。我發現那解釋了他們出現在這裡的原因並加強了我們一定要快點動作的信念。',0);
