INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10002,'zhTW','<塞洛莉婭對你點點頭。>$B$B做得好。我們替自己爭取了一點時間。血精靈會對他們朋友發生的事開始好奇。希望到那時候，我們會更瞭解他們的意圖。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 10003 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10003,'zhTW','<凱德對你點點頭。>$B$B做得好。我們贏得了一點時間。血精靈會對他們朋友發生的事開始好奇，我們會更瞭解他們的意圖。$B$B等到時機到來，我會告訴羅卡格我們的進度。',0);
