INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10126,'zhTW','艾瑪利安的盾、劍和其它貴重物品似乎被隨便扔到一旁。囚犯似乎在被解裝之後沒多久就被押解走了。',0);
