INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10154,'zhTW','我看見過那些擲彈兵在戰鬥中使用這些東西。這種炸藥好像大多數時候都可以確實引爆，並且造成相當的爆炸力！讓我們測試它們。',0);
