INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10155,'zhTW','我本來開始懷疑我們再也看不到斥候瑪克哈的訊息，不過你已經證明我錯了。$B$B沒有多少時間可以慶祝了，把他們的計劃告訴我。你成功的切斷他們西邊的軍力，但是仍然有相當大的敵軍集結在塞斯高。',0);
