INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10159,'zhTW','隨著掠食者被清除了，那些往返於贊加沼澤去塞納里奧庇護所的旅人應該會比較輕鬆了。$B$B塞納里奧遠征隊感謝你。',0);
