INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10160,'zhTW','<阿曼蒂中尉點頭。>$B$B非常好，我們需要所有我們能取得的幫助。在南方堡壘附近持續增加的邪獸人使我憂心。我派了一個斥候去調查，但是他還沒有回來。',0);
