INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10161,'zhTW','這些零件有的歪七扭八的，但是應該足夠這裡使用了。隨著一些充滿創意的行為，我有自信能夠讓它起作用！',0);
