INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10162,'zhTW','你似乎從一出生就擅長飛行，$N。表現得很不錯！雙足飛龍的身上甚至連一道抓痕都沒有！',0);
