INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10164,'zhTW','你做到了，$N！靈魂被釋放了！$B$B雖然我沒有一個物質上的表示，但我仍然能以來自精靈世界的物品獎賞你。小心使用，像這樣的物品經常是具爆炸性且能更使它們的使用者受到重大傷害。',0);
