INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10176,'zhTW','你做得很好，$N。摧毀這個結界將有助於我可以更容易的解除這個塔的詛咒。',0);
