INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10177,'zhTW','該是你抵達的時候了。麥莉莎說她送出幫忙需求已經好幾天了。但是我們在這裡戰鬥的時間比那更久！',0);
