INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10185,'zhTW','<管理者看起來很沮喪。>$B$B我幾乎可以預見從地平線湧出的下一波。除掉他們暫且是可行，但仍需要長久的評估。',0);
