INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10186,'zhTW','哇！看起來很劣質呢。也許我們可以將它們使用在第三引擎歧管？$B$B儘管如此，做得好，資淺技師第三級！你很快就可以變成資淺技師第二級了。',0);
