INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10187,'zhTW','<你描述在下面那個廢墟的經過以及傳達管理者的訊息。>$B$B那真是個好訊息。由於你的持續幫忙及一點小運氣，我希望不久之後能夠加入他們。我們最後一定能夠向凱爾薩斯復仇的。',0);
