INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10190,'zhTW','嘿，小心你用那個指到的東西！你已經把它的功能設定成“殺”！看起來你已經把電池充滿電，其它的也是。這樣我的機器人就可以繼續運作，你幫了我一個大忙。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 10191 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10191,'zhTW','你做到了！你做到了！我要親你！$B$B喔，該死……麥克斯米林V型又要沒電了。啊阿還好，它還夠維持到完成這個工作，那才是最重要！$B$B火箭主管弗斯拉格會很樂意將這些德萊尼機械吊掛在X-52虛空火箭裡的！那表示是對我的升等！我好開心阿，我一定要給你獎勵！$B$B來，從這些裡面挑一個吧。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 10192 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10192,'zhTW','<大法師瓦格斯的影像看來像在檢查這本手冊。>$B$B表皮有點受損，但想想它遭遇過的事，能夠儲存著真是個奇蹟。護送它，$N。沒了這本書，我們打破塔的防禦的機率就變小了。',0);
