INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10212,'zhTW','你真是瑪格漢的英雄，$N。要不是你，我們一定已經被食人魔及破碎者侵犯了。$B$B我們是貧窮的人，但是我們還是有一些不錯的東西。請吧，我認為你值得這些獎勵。',0);
