INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10213,'zhTW','我們是被燃燒軍團擊中墜毀的，雖然我們有揮舞休戰的旗幟。誰知道燃燒軍團會這麼殘暴？$B$B我們不能跟你去斷背崗哨。我們需要修理我們的飛艇並重新上路。',0);
