INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10218,'zhTW','看看工匠莫法魯斯的點子的成果，我決定讓他復職了。做得好啊小噬屍獸。的確是做得好！$B$B記住，要是你想找工作或是到虛空風暴的時候，到風暴尖塔來找我。',0);
