INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10232,'zhTW','好吧，有好訊息也有壞訊息，是吧？我們給了他們一擊，但隨著燃燒軍團遍佈整個虛空風暴上……並且更接近我們了……',0);
