INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10233,'zhTW','<巫師上尉莫爾蘭嚴肅的點頭。>$B$B肯瑞託很難從建築物本身的利益來欣賞它，但我們並不會因為對抗敵人而覺得良心不安，就算死的也一樣。',0);
