INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10234,'zhTW','我認為這些都得現在就去做了。只要我們能夠將他們嚇跑。$B$B嘿，這讓我想到了個辦法！',0);
