INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10235,'zhTW','他，嗯……他說什麼？他們將要侵犯52區？！$B$B喔，這太糟了……糟透了！',0);
