INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10239,'zhTW','<莫爾蘭小心翼翼地處理其中一個容器。>$B$B我不相信我之前曾看過任何跟這一樣的東西。一定有很多的能量懸浮在這裡，但是是以原始的狀態。我們得小心處理，不過我想我們能找到方法來改寫這些能量進而協助抵擋那些法力生物。',0);
