INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10244,'zhTW','魔能機甲製造手冊？！你看過它了嗎？喔，別在意……沒人看過這個手冊！$B$B喔喔，雖然我希望我有時間可以仔細研究它。但我們需要將這本書送回52區！',0);
