INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10262,'zhTW','這些徽記是一個好開始。$B$B不幸的是，當你在聚集之地時，我在薩希斯的其它密探其中之一捎話給我，星界強盜奈薩德還活著！',0);
