INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10265,'zhTW','讓我看一下那東西。$B$B嗯，看來似乎沒有什麼特別的。我懷疑這就是那個東西嗎，雖然你所描述燃燒軍團在廢墟活動的方式，聽起來好像他們正在尋找某些特別的東西。$B$B讓我們期望這不會是節點親王那麼想擁有的水晶。',0);
