INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10266,'zhTW','沒錯，是真的。血精靈在另一批已經送達的貨物買賣上食言了。$B$B因為虛空獵手卡爾伊對你的保證，我希望你能在這件事情上協助我。',0);
