INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10267,'zhTW','嗯，我個人對於解決了這樁小生意感到很開心。我不記得何星界財團何時與那樣粗野且無法信任的生物交易過。$B$B不過，你好像很值得信任，$N。或許你不介意幫我更多的忙？',0);
