INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10268,'zhTW','歡迎來到風暴尖塔，$C。請享用星界財團的殷勤招待。$B$B你可以將那個裝置放在任何地方。我猜你可能很快地就要背起它了。',0);
