INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10269,'zhTW','<商人哈斯辛降低他的聲音變成耳語一般。>$B$B啊，我知道你的任務。這對節點親王哈拉邁德來說非常重要！$B$B既然我們知道第一個三角測量點的位置，你必須迅速動身去找到第二個！',0);
