INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10270,'zhTW','這個電池應該要為了我們的目標保留。一旦錢進帳後，我們就能將它改良得更好。$B$B有這樣的東西就夠了。每個討論的片段都會造成利益的損失。',0);
