INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10274,'zhTW','做得好，$N。的確做得很好。虛空龍族最初不願接受一條藍龍混在他們之中，但是隨著時間和我堅定的展示權威，他們會到這裡這。分佈的，單獨的，沒有一位可靠的領導人，我們必須警戒避免它們落入邪惡力量的統治，永遠保持他們的控制權。',0);
