INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10275,'zhTW','的確非常好。節點親王會很高興！$B$B我們現在知道第2個點了，它將告訴我們第3個點在哪裡，以及水晶的大概位置！',0);
