INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10276,'zhTW','出乎我最瘋狂的想象之外，我從沒想到你能取回水晶！$B$B還真的將它交給我！你知道它有多麼強大嗎？$B$B你的無私是鼓舞人心和無可非議的，$N！你給了我許多值得思考的事。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 10277 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10277,'zhTW','希望你現在對於在等著你的東西有更多的瞭解。',0);
