INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10278,'zhTW','難以相信。你碰觸了虛空本身！$N，你保住了我畢生的研究。不過還有更多事必須完成，而你可以幫助我。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 10279 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10279,'zhTW','我們必須幫你準備好進行即將發生的戰鬥……',0);
