INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10284,'zhTW','你完成了一件偉大的事，$N。哎呀，這個年輕大酋長對這些事件的回憶一定和當時分毫不差……安杜姆就在主人的藏身處等著你。',0);
