INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10288,'zhTW','回報榮耀堡嗎？沒問題——我的獅鷲將安全迅速地帶你到那裡！',0);
