INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10290,'zhTW','啊，是的。這種等級確實是我所期待的。假如我們能從巨人身上取得穩定的進貨來源，我們也許能完全的放棄開採水晶礦。',0);
