INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10291,'zhTW','我們已經在這個該死的荒原失去了許多勇敢的戰士。我不想再派更多的新兵去送死。$B$B<納茲格雷爾透過他殘破不堪的狼型面罩嚴厲的怒視著你。>$B$B反正，假如克拉庫克克將軍派你來見我，那就表示你有可取之處。那麼你的意思呢，$N？你願意榮譽地為你的大酋長服務嗎？',0);
