INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10292,'zhTW','<祖班·艾貞努比露出了像虛靈組織一樣齜牙咧嘴的笑容。>$B$B我保證只會把這個難以置信的火力用在善良的用途。這個善良的用途就是我賺取的利潤。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 10293 AND `locale` = 'zhTW';
