INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10296,'zhTW','的確，如果獸人從未到達艾澤拉斯，今日的聯盟也不會存在。遲早內戰將爆發，更進一步減弱人類王國。$B$B最終燃燒軍團將侵入艾澤拉斯，在沒有任何防衛者的情況下毀滅它。',0);
