INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10355,'zhTW','<洛安瑪檢驗了那些樣本，看起來很憂傷。>$B$B這正是我所擔心的，$N。逐漸乾枯的環境對那些從沒想過要住在沼澤以外的生物造成很大的負擔。我們只好繼續觀察該區域然後跟塞納里奧遠征隊協商看看我們能做些什麼。',0);
