INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10379,'zhTW','啊，年輕的$g牧師:女牧師，我很高興你回來這裡。我會幫你上一堂令你永生難忘的課。你準備好了嗎？',0);
