INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10380,'zhTW','那時就完成了。我們來這裡，奉我們大師們的命令來獵殺它們。完全不留餘地。$B$B有時會讓你心存懷疑。',0);
