INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10381,'zhTW','你帶來的壞訊息令我滿心悲痛。我們兩個協力抗敵，而最親愛的沙塔斯之子卻失去了他的方向。',0);
