INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10384,'zhTW','<你將資料單元交出讓阿米爾可以閱覽這個計劃。>$B$B沒事……該死！他們是很聰明沒錯但是絕沒有阿米爾那麼聰明！$B$B我將要求你去做的事情非常危險。要是你不想繼續的話我可以理解，凡人。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 10385 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10385,'zhTW','復仇軍之所以存在的原因現在完全瞭解了。$B$B復仇軍不是到這裡獵捕迪門修斯！他們想在這裡操控虛無！$B$B他們在這個法力熔爐裡操作虛無能量以結合他們自己的能量成為一種叫做奈薩斯潛獵者的生物。$B$B他們毫無疑問地使用一臺原始加速器去完成轉化過程。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 10386 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10386,'zhTW','前線指揮官托爾克派你來找我是對的，$N。我可以讓那些有勇氣拿起武器對抗燃燒軍團的人發揮用處。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 10387 AND `locale` = 'zhTW';
