INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10398,'zhTW','你回來了真好。我們必須殺死阿苟納之池的首領。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 10399 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10399,'zhTW','我預見了這場偉大的勝利，$N。今日，神聖的納魯偏愛你。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 10400 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10400,'zhTW','讚美聖光，我就知道你可以的！阿拉休斯和他的爪牙被消滅了！軍團很快就會滾回家，我們將再度的安全了。當正義被彰顯，我們也就可以回家。$B$B謝謝你，$N——聯盟及洛薩之子今日以你為榮！',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 10401 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10401,'zhTW','做得好，士兵。的確，做得很好。這最少為我們掙得另一個月的時間，或許可給我們足夠的時間去弄清楚地獄火堡壘裡發生的事。$B$B現在有關獎賞的部分……',0);
