INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10403,'zhTW','你是來幫助我的部族的嗎，$r？真不尋常。沒有多少人會關心這塊土地上的破碎者命運。',0);
