INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10407,'zhTW','你對我們理想的奉獻足以作為模範，$N。現在我們已經擁有了索克雷薩之石，只剩下一件事情需要去做。',0);
