INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10413,'zhTW','什麼！？你跟一個虛無恐獸交手？而且還活著？！難以置信！$B$B這個樣品比等重的黃金還有價值，像這樣的發現應該要好好獎勵。',0);
