INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10481,'zhTW','讓我為你克服如此艱鉅的任務而獎勵你，英雄。$B$B現在，我們必須進行我們的工作！請站後面一點，這樣我才可以將圖騰放在這並釋放這些靈魂。',0);
