INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10546,'zhTW','<伯拉克沉默了一會。>$B$B我已經監視這些血精靈好幾個禮拜，我想找出他們把第三塊詛咒密碼藏到哪裡去了。$B$B當前為止，我無法得到任何線索。我只知道伊利丹每天都會從黑暗神廟派一位使者來這裡。$B$B這個使者身邊守衛森嚴。我已經跟蹤他一個禮拜，想找出將使者跟他的守衛分開的方法。可惜，那些守衛從不離開他的身邊。',0);
