INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10557,'zhTW','哦，你成功了！而你身上連一處瘀青還是骨折都沒有！你看吧，我告訴你一切都會順利成功的！$B$B這是給你的報酬，$N，雖然我當初多算了醫療開銷而你用不上……所以算你賺到了！',0);
