INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10569,'zhTW','<基爾蘭快速地翻閱日記頁面。>$B$B大部分的內容都難以辨識，但是我可以東拼西湊的看出內容是關於一個偏向邪惡的法術準備儀式、受害者還有墮落的場景。還有一個奇怪的註明關於一個“背棄者”。',0);
