INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10570,'zhTW','<伯拉克從你身上拿走了信件並且閱讀它。>$B$B這些耍小聰明的精靈！這是伊利丹的指令，指示他們下一封密信藏在哪裡。很顯然的，他們一直更改藏信的地點。這封信件並沒有告訴我們下一封密信藏在哪裡……假如我們可以把這封公文送到他們的手上，我們就可以知道他們藏匿下一封密信的地點。$B$B可惜這封公文的封條已經被拆開了，要交還給他們已經不可能了。$B$B嗯，現在還不行……',0);
