INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10584,'zhTW','太棒了！反正你幫我們取回來的電源能量可以讓我們的機械運作好一陣子了。$B$B當ZC號的電源耗盡的時候還真是一個沒用的東西！$B$B我希望取回電流體的這件事不會太困難。我有別的事情想請你去做，而我有預感這將會有一點危險。',0);
