INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10586,'zhTW','<你向空軍指揮官回報並且交給他奪回的檔案。>$B$B擊敗戰爭使者瑞術恩可能表示我們與燃燒軍團之間的戰事已經劃下句點了，但是這些檔案中的描述顯示出他們的計劃遠比我想象中還要大許多。恐怕我們還有很多事情要做。',0);
