INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10587,'zhTW','讓我們靠近一點看這些武器，$N。嗯……這還真是令人不安啊。',0);
