INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10592,'zhTW','這些石頭帶著一個我不想記起的汙點，但我也無法忘記。你把這些帶來給我是在考驗我的耐心。$B$B不過，很清楚的，你和我尋求一樣的復仇，我會幫助你並給你指示。',0);
