INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10593,'zhTW','女妖之王將你引導的很好。這確切是我需要去結合碎片的東西。$B$B<當藤蔓穿過碎片交織時，米哈爾注視著並把他們捆在一起。>$B$B那裡！天災毒物，我將召喚它。當你使用它時，謹慎小心，因為它違反它的意願為你效勞。',0);
