INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10594,'zhTW','哇，這真是太棒了！我實在搞不清楚……就好像這些水晶是有生命似的。$B$B我在想這些水晶跟虛空龍之間有沒有某種特殊的關聯性？$B$B謝謝你，謝謝！你一定要收下我的一點感謝之意，一些我的零件和完成品珍藏。$B$B他們之中一定有一個適合你。',0);
