INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10595,'zhTW','你可以在這場大屠殺當中存活下來讓我印象深刻。你可能就是我們要執行危險任務的最佳人選。',0);
