INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10637,'zhTW','希望你製造的混亂可以幫我們爭取到足夠的時間，讓我們對卡拉伯爾廢墟訓練場有充份的瞭解。',0);
