INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10640,'zhTW','你竟然大老遠的跑來找我，陌生人。我很驚訝派你來的人竟然知道我是誰。',0);
