INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10642,'zhTW','<索魯斯開始用灰燼樣本製造某樣東西。>$B$B做好了。看，顯靈鏡！',0);
