INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10666,'zhTW','<大衛一邊匆匆的翻閱著那本書，一邊顫抖著。>$B$B這可不是一個可以開玩笑的東西，$N。在武器製造完成的時候，我會毀掉它。即使這些文字不公諸於世，世界上的惡魔力量也已經太多了。',0);
