INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10670,'zhTW','<大衛·偉恩將這個寶石舉高，透過陽光欣賞著它。>$B$B這個寶石真是毫無瑕疵呀，而且這正是我們所需要的。一個有瑕疵的寶石將會危害將來揮舞這把劍的人，造成劍中的附魔效果反撲其主人。',0);
