INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10690,'zhTW','難以相信。你獨自一人殺死雷瑪了嗎？$B$B以你的外表，我認為你能。你知道，我們正在尋找年輕、強壯的$C，像你那樣，在這周遭幫忙，特別是我們與巨魔們持續有的那些問題。確定在那可能性上你會與我做後續聯絡。$B$B好的，你已經明確贏得我釋出在那張通緝佈告上的賞金。$B$B請，選擇你想要的。',0);
