INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10692,'zhTW','做得好，$N。在殺死瓦瑞迪斯時，你已結束了伊利丹最危險的計劃之一。$B$B在這之後你的名字將確定會四處傳播。$B$B請允許我取走惡魔之名寶典的遺稿。我保證它將被正確地……處理。',0);
