INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10694,'zhTW','非常好！你肯定做出了巨大的犧牲才能獲得這些榮譽徽章，為此你將得到充分的肯定。正是許許多多像你一樣的冒險者讓一切都變得不同的。$B$B如果你還有更多榮譽徽章的話，儘管來找我，我很高興能為你做點什麼。',0);
