INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10748,'zhTW','知道我們敵人的首領已經被解決掉使我們現在可以鬆一口氣了。不只如此，你還守住了整片山區免於受到他們的破壞。$B$B不管他們最終的目的為何，你都把他們擊退了！$B$B我們對你感激不盡，$N。請收下這個以表我們的敬意，還有我們無盡的歡迎。',0);
