INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10780,'zhTW','<帕沙恩接過斯克瑟隆羽毛，搖著頭。>$B$B如果他們那天死了，就會更好一點兒，但是不會那麼簡單的。那古爾丹的魔法將會把他們變成他們試圖制止的威脅，是一種特別殘酷之命運的扭曲。',0);
