INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10781,'zhTW','赤紅法印將會受到調查。他們威脅了德拉諾的所有生命。我預見了他們的黑暗主人有天必須對他的罪行負責。或許將是你將他送交審判，英雄。',0);
