INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10784,'zhTW','<吐查克明顯的點了點頭嘉許你殺敵的勇猛。>$B$B你持續的讓我印像深刻，$N。每一次打倒一個食人魔之時，我們就更進一步擊退了我們的仇敵。',0);
