INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10785,'zhTW','嗯，一個由龍火的精華製作的陷阱嗎？我很好奇沙伯邁恩是如何得到這種稀有的物質嗎？$B$B那一點都不重要。重要的是我們將用它來殺死一個格魯爾的兒子！',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 10786 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10786,'zhTW','<吐查克露出牙齒笑著關於你告訴他那些你在圓面之地冒險的故事。>$B$B嗯，我真希望我也在場。讓我告訴你某些事情，$N∶決不要接受妨礙你戰場光榮的任何職責！$B$B哈！在所有食人魔都被你殺死之後，在這些山裡還有剩下給我的嗎？！',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 10787 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10787,'zhTW','<雷克薩自豪地向你點頭。>$B$B只有真正的英雄傳奇能敘說你所展現的偉績，$N。你已經加入他們的行列了！$B$B但是現在，如果我們要擊敗苟克，還有一件最後我們必須做的事情。$B$B把屍體給我，而我將利用它創造出某些能將使他心生恐懼，並且只能選擇在榮耀的戰鬥中面對我們的！',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 10788 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10788,'zhTW','環遊世界的大忙人終於回來了……$B$B我希望你聽出我話中的譏諷，$N，因為一再派人找你已經造成我非常大的麻煩。我考慮到你可能以毫髮之差就會被惡魔守衛給活活燒死，而他們根本沒有任何頭髮。$B$B專心學習，這可不是你有機會能再修到的一門課程。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 10789 AND `locale` = 'zhTW';
