INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10895,'zhTW','我能看見這裡的煙和火焰！做得好，$N！我們獅鷲騎士對你的讚揚可不只一兩句而已——你剛剛的行為非常勇敢……',0);
