INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10901,'zhTW','終於！$B$B掙脫了這些束縛，鬥棍也重回我的身邊，我就可以把那個深海女巫送回冰冷的深淵去……',0);
