INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10902,'zhTW','假如你帶來的這些東西是指標的話，那就表示你對藥劑很有心得。你將會是個很好的學生。$B$B這些精華將會提供我足夠的材料來調配我的配方。我的發現將會使我在所有的鍊金師中非常出名！$B$B現在，假如你願意學習的話，我就願意教你。',0);
