INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10916,'zhTW','你已經找到祈禱珠串了！做得好，$N。你的確是不可思議——前一刻你殺死地獄火半島的魔物然後下一刻你找到失落的寶物。像你這樣的人真會鼓舞他人！$B$B你能找回這些珠串真好……因為它們在接下來的驅魔儀式裡面是非常重要的。',0);
