INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10917,'zhTW','<威卡斯在你向他呈獻敵人的遺物時發出歡愉的叫聲。>$B$B太好了，這樣就可以告訴斯克提斯我們流亡者不會靜靜的躺著等他們進攻。這裡是我答應要$B$B給你的報酬。我可以安排再多給你一些報酬，只要你幫我拿來更多的羽毛。',0);
