INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10921,'zhTW','這些蜘蛛已經被打敗了。你已經殺了許多，而且連他們的蛛後都在你面前倒下了。我已經中毒太深所以無法以戰鬥的方式獲得自由。$B$B請從我的裝備中挑幾樣帶走吧。這樣可以減輕我的負擔而且提供你轉至沙塔爾前哨的回程所需的工具。',0);
