INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10930,'zhTW','太神奇了！看看這個器官！這叫阿貓阿狗的東西竟然有某種粉塵在它阿貓阿狗的器官裡面。噢！我還是不要用那些科學術語令你厭煩。我倒是從幼蟲身上拔出一些牙齒製作這些異常鋒利的刀。想要一把嗎？',0);
