INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10936,'zhTW','你來得正是時候！我從那個德萊尼牧師那邊聽說了你最近的訊息。你嚇壞了我的信差！$B$B既然你已經完成了那些事情，我幫你策劃了一個小任務需要你去地獄火堡壘一趟。',0);
