INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10937,'zhTW','在我聽到你親自向我回報之前我都不敢相信那是真的。我們的斥候已經陸續回報，那些碎手氏族少了他們親愛的訓練員指揮他們，當前已經陷入一片混亂。$B$B你已經歷經了長途的跋涉，$N。我相信你會接受這個護甲還有我的感謝。光榮的穿上它吧，這是你應得的！',0);
