INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (10971,'zhTW','看起來他的功能不只是辨識身份而已。標籤上有一些用某種密碼編寫的文字。我就快要破解它了，也許只要再幾片就可以了。',0);
