INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11019,'zhTW','你不會以為我們要讓你獨自面對邪獸人軍隊吧？$B$B<亞茲爾的雙眼清楚的閃過一抹憂鬱。>$B$B是的，我們都在這裡陪你，$N。你為了奪回靈翼之龍土地而執行每一個邪獸人任務時，我們都在你身旁確保他們遭受足夠的挫敗。$B$B你要低調一點才不會在破壞任務中給自己引來不必要的麻煩。',0);
