INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11020,'zhTW','<亞茲爾低聲私語。>$B$B做得好，$N。低調一點。明天再來找我，我們可以再做一次。',0);
