INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11021,'zhTW','你帶來了什麼東西？我無法辨識書中的文字，$N……由於流血的緣故……影響了我的視力。',0);
