INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11022,'zhTW','感謝這位$g先生:小姐，很高興你在離去之前決定跟我再次談話。',0);
