INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11035,'zhTW','<亞茲爾低聲的跟你說話。>$B$B你幫了靈翼之龍一個很大的忙，$N。我們會慢慢地打垮那些龍喉獸人。他們內部開始感染一種疾病——一種沒有解藥的疾病……$B$B假如你有興趣繼續在龍喉空港執行任務的話，明天再來找我。',0);
