INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11036,'zhTW','<主管檢視木箱裡的東西。>$B$B看起來都不錯。清單上的專案又完成了一樣。現在我們所要做的就是讓火箭離開地面！',0);
