INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11037,'zhTW','<主管聽你描述關於先知所預見的景象。>$B$B嗯，關於這件事情我一無所知，但我們倒是非常需要你的幫忙。看看我身後的巨大火箭！那就是X-52……$B$B是不是你見過最美麗的火箭呢？',0);
