INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11038,'zhTW','所以你來這裡是為了幫我們找出凱爾薩斯在策劃什麼陰謀嗎？非常感謝你的幫忙。虛空風暴充斥著血精靈密探，他們所從事的秘密行動已經使這片大地面臨被分化的危機。',0);
