INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11039,'zhTW','<間諜大師的臉上露出了短暫的失望表情。>$B$B我原本期待的是至少一個小隊的援軍，但是假如沃雷塔爾認為只有你適合這個工作，那麼我會跟著調整我的計劃。',0);
