INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11040,'zhTW','我連某些零件是用來幹嘛的都不知道！我確定我可以利用其中一些零件，但我從來沒想過我必須學著用侏儒的方式來思考！',0);
