INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11043,'zhTW','<拉瑟爾的臉色漲紅，直到在他的鬍鬚下逐漸退去。>$B$B他想對我的獅鷲做什麼？$B$B假如那個小混蛋在獅鷲上裝了獸鞍以外的任何東西的話，我就要親自飛去刀鋒山把他說的什麼火箭插進他的喉嚨裡！',0);
