INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11044,'zhTW','你說夢境？我才不管他是夢見、有人寫信告訴他還是由一個深淵領主親口告訴他。他真是沒用！重要的是你來到了這裡，我的朋友。我們需要集結所有的力量。',0);
