INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11046,'zhTW','芬提的記憶力很好。我上一次去撒塔斯城買藥劑材料已經是一個月前的事了。但是，他說的沒錯。我需要幫忙。',0);
