INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11047,'zhTW','<達瑪聽完了阿迦爾的請求。>$B$B我無法保證會有多的雙足飛龍，但是我會盡力幫忙。因為我們連其它買家以及哨站所訂購的雙足飛龍都無法準時交貨了。',0);
