INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11048,'zhTW','<古爾穆克對克洛坎的決定抱怨連連。>$B$B我瞭解他的難處，但是我們這裡的戰壕同樣也需要人員的補充啊！燃燒軍團日夜不停的以惡魔火炮轟我們。假如克洛坎行程耽擱的話，他的缺就由你來替補吧！',0);
