INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11070,'zhTW','嗯看來現在只有你和隊長了，蠻兵。祝你好運！你會需要的！',0);
