INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11071,'zhTW','我從沒想過會有人那麼厲害能擊敗碎天者。你知道這代表了什麼意義吧？你現在是頂尖獸人！你一定要守住你的頭銜。',0);
