INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11072,'zhTW','太好了！收下這個。我用你取得的物品準備了這個包裹。它們會讓你召喚泰羅克。$B$B小心，$N。他是世界上最強大的鴉人。別小看他！',0);
