INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11075,'zhTW','礦工都很努力工作，但他們沒有人敢多踏進礦洞裡一步。他們寧願死也不要到深處採礦！你要完成他們不能做到的任務。',0);
