DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 11090 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11090,'zhTW','他還會回來的，但現在燃燒軍團對伊利丹大人的攻擊已經減弱了。他應該知道你的功績，$N隊長。',0);
