INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11115,'zhTW','把它燒掉，$r。全部燒掉！他們什麼都不該擁有！聽到了沒！不留一物！他們必須為他們過去以及將來所犯下的罪行付出代價。$B$B如果我能掙脫這些可惡的枷鎖，我將親自殺死瓦許。$B$B或是你想做奈普圖隆的工作？我將授予你進入毒蛇神殿洞穴所需的標記，但是首先你必須為我帶來組成這根神聖鬥棍所需要的物品。$B$B你有這個意願嗎？',0);
