INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11119,'zhTW','不管凱勒怎麼說，我仍認為我們的任務是需要循序漸進的。$B$B沒錯，我們在經過那裡的時候會補給天空衛隊。前提是我們要能待得夠久。$B$B你看起來願意替我們清除虛靈組織。如果你可以撐得夠久，我們就會賣給你水晶熔爐製造的剩餘物品，所以帶著你的聖物碎片和水晶吧！$B$B我們$4581d後出發。',0);
