INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11124,'zhTW','<調查員以一種不信任的眼神看著你。>$B$B我聽說你要來……協助這次的調查。好得很。$B$B我在廢墟使用這些粉塵，來幫助我尋找可能辨認出攻擊者的線索。它會讓任何與攻擊相關的痕跡發光。不要猶豫去檢查所有可疑的東西。',0);
