INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11126,'zhTW','做得好，$N。我想我們已設法在他們還沒準備好時將他們揭發了。他們的間諜可能曾經認為待在城裡就安全了。$B$B我想一段時間之後，那些煽動者又會回來散佈他們的謊言。我們要用你爭取到的時間進一步地讓他們閉嘴。',0);
