INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11127,'zhTW','你拿到了！好$G傢伙:小姐！我希望葛瑞姆沒給你添麻煩。來，這是我答應過的酬勞。和你打交道很愉快。喔，別向旁人提起這樁小交易，行嗎？',0);
