INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11128,'zhTW','<軍情七處的探員讚許地點點頭。>$B$B幹得好。我正好有個計劃讓這些叛逃者身敗名裂，在塞拉摩沒有立足之地。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 11129 AND `locale` = 'zhTW';
