INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11136,'zhTW','<上尉毫不掩飾地在評估著你的能力。>$B$B你聽說了最近在海岸邊發生的船難？很好，我需一些幫忙來確認我對那些倖存者的一些疑慮。歡迎，$N。',0);
