INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11137,'zhTW','<維摩爾上尉從你那邊收下了指令並且仔細地閱讀。>$B$B這個“珍貴的貨物”指的是什麼？迪菲亞確實有在暴風城一帶進行一些小規模走私，但這看來完全超過了他們的範疇。而且這樣的文字明顯是出自於一個富豪或是貴族贊助人。',0);
