INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11138,'zhTW','<雷恩看著那些指令。>$B$B所以那艘船上有些有價值的貨物！我們一定要在迪菲亞發現之前先找到它們。他們並不是潛水員，但如果你要幫我一起找那些貨物的話，我們就會需要他們的一些裝備。',0);
