INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11139,'zhTW','哇喔，這裝備的狀況比我想得還嚴重，還有這些工具……$B$B好吧，既然我說過要幫你把裝備修好，我最好現在開始動手。',0);
