INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11140,'zhTW','<雷恩將你發現的保險箱中的東西一掃而空。>$B$B做得好。現在，讓我們來瞧瞧我們“珍貴的貨物”有沒有在裡面……',0);
