INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11141,'zhTW','你和雷恩做得很好，發現這個情報並且立刻回報是正確的。現在，我們必須確認你的發現。如果我們弄錯了，牽連實在太廣。',0);
