INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11142,'zhTW','<吉安娜女士專心地聆聽你空中偵察的報告。>$B$B一個符文法陣，龍類生物？迪菲亞兄弟會與“她”結盟了？那個叛徒？$B$B<吉安娜女士平復一下自己的情緒，準備要向你解釋。>',0);
