INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11143,'zhTW','維米斯上尉認為恐怖圖騰與樹蔭旅店的摧毀有關？他們並不是我最懷疑的物件，但是維米斯上尉既然派你來繼續追查，他一定有他的理由。更何況，恐怖圖騰已經成為我們的芒刺好一陣子了，我們非常高興能有額外的幫手。',0);
