INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11144,'zhTW','<達利爾上尉粗略地看了一下作戰計劃。>$B$B沒有比這更明顯的證據了。他們打算自己對抗在這個區域殖民的人類，我懷疑塞拉摩就是他們的下一個目標。',0);
