INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11145,'zhTW','從黑蹄村被釋放的俘虜已經開始回報了。俘虜所提供的情報讓我們能在下一次對抗恐怖圖騰的戰鬥中取得優勢。$B$B我和我的手下們衷心地感謝你。',0);
