INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11146,'zhTW','你看起來受了一點抓傷，不過不太嚴重。你的遭遇絕對會比那些恐怖圖騰遇上我們的新朋友來得好呢。',0);
