INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11148,'zhTW','<達利爾上尉檢查著你從黑蹄村帶來的武裝。>$B$B毫無疑問，他們完全符合，但還有一個問題——這些武裝從來沒有用在戰鬥中。黑蹄村一定不是沼澤中唯一的恐怖圖騰據點。',0);
