INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11150,'zhTW','我希望恐怖圖騰收到我們的警告了。任何再回來的企圖將會遭遇比被火燒還慘的後果，這一點我和我的學徒們能跟你保證。',0);
