INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11151,'zhTW','<上尉專心地聆聽你的報告。>$B$B我們已經替詹姆斯和他的家人復仇了，但這也無法讓那些被摧毀的事物回覆舊觀。',0);
