INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11152,'zhTW','<在你講述海厄爾家族墓地的事情時，維米斯隊長露出了一點淡淡的笑容。>$B$B他們能瞭解真的很好。你沒有跟他們談起詹姆斯的事吧？$B$B我會把他妻子的訊息傳給他，不過我很懷疑他能明白。',0);
