INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11158,'zhTW','<布洛格收下那些羽毛。>$B$B布洛格對這些羽毛感到很滿意。魔力很強。布洛格不知道迅猛龍如何給這些羽毛力量，但迅猛龍羽毛總是最適合儀式了。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 11159 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11159,'zhTW','布洛格感謝你的幫忙，雖然他知道莫格穆洛克大王一定不會感謝你。起碼倖存的石槌終於可以專心面對生者的問題，而讓死者獲得歸屬。布洛格現在只剩下一件事了。',0);
