INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11161,'zhTW','布洛格感謝你，$N，一旦布洛格把這些魔法加進圖騰裡，就可以使布洛格死去的朋友獲得救贖。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 11162 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11162,'zhTW','<布洛格聽你講述在奧妮克希亞的巢穴入口的情況。>$B$B布洛格料到奧妮克希亞膽小到不敢出來面對你。就像黑龍軍團總是等到確定勝利時才願意出擊。$B$B布洛格很感謝你的幫助，$N，布洛格永遠不會忘記你替他做的。布洛格永遠也不會放棄讓石槌回到故鄉的任務。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 11163 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11163,'zhTW','<多娜四處張望了一下，然後開始對你低語。>$B$B$N，我接下來要說的，請務必保持機密，瞭解嗎？$B$B我是被沙塔斯保安官派來滲透巴德的手下。我得承認，自從你來了之後，你是我在調查中最感興趣的關鍵人物。$B$B但是你的行動已經排除了你的嫌疑。事實上，你殺死了瘋狂的督軍祖爾金，我已經強烈要求要獎勵你的努力。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 11164 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11164,'zhTW','啊哈，這是我需要的！$B$B是我先前答應過的報酬，$C。',0);
