INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11175,'zhTW','呃，我就知道！他真是超超超超超超級保護過度！真是丟臉。$B$B不過我也很高興你來了——我們全都是，我們很需要你的幫忙！',0);
