INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11191,'zhTW','太好了。我正好需要你的大力幫忙。我的首要工作就是重新點亮那盞燈。',0);
