INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11192,'zhTW','老實說，我有點懷疑，但這是現在唯一可行的辦法。一旦我們讓那座燈塔重新運作，我相信就有時間可以尋找其他方法提供那盞燈燃油了。',0);
