INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11193,'zhTW','嗯，巴布還真好心叫你送來給我。我不知道你看過這本書了沒，不過書中的故事有許多都是真的。你也知道它們並不完全是水手們虛構的。',0);
