INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11194,'zhTW','原來你想聽關於深海怪物的事蹟嗎？嗯……這樣吧，我跟你打個商量，但是就你的方面來說將會牽涉到很多的酒精以及一些尷尬的場面。',0);
