INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11196,'zhTW','他們抓住我的時候，幾乎把我所有的東西都拿走了，但過來點——不好意思麻煩你，所以收下我最後的一點銅板吧。$B$B除此之外，我還可以留在這裡提供一點服務……',0);
