INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11198,'zhTW','幹得好，$N！我得承認，當我第一次看那個怪獸的時候，我懷疑我們能不能守住碼頭，但你卻漂亮地使守軍團結在一起！',0);
