INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11200,'zhTW','<克羅格檢查你從黑蹄村帶回來的武器和裝備。>$B$B這肯定是莫薩恩的作品。詢問莫薩恩可能會引起太多的關注，但我們在對付恐怖圖騰上仍有其它的選擇。',0);
