INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11212,'zhTW','多虧了塞拉摩派人來找我。你那個守衛朋友說的沒錯。我們附近來了一些新鄰居，而他們可不懂得敦親睦鄰。',0);
