INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11213,'zhTW','幸好納澤爾想到派人來看看。我們附近搬來了一個新的鄰居，而自從他們建立營地之後就不斷的製造麻煩。',0);
