INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11217,'zhTW','感謝你！這將使我們能在莫希從飛艇失事地回來之前繼續從事一些野外的活動。',0);
