INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11218,'zhTW','礦石帶給你奇怪的感覺？也許我們根本就不會用到那些東西。$B$B<斯迪爾林看了看，往後退一步，然後改變了話題。>$B$B這些寶石看起來真不錯！不知道我可以從中得到些什麼？當然啦，總是有舊東西要修、新東西要做。$B$B你知道嗎，我真的覺得跟你一塊兒工作有很多油水可以撈。收下這些……至少，這是我能做到的！',0);
