INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11219,'zhTW','火勢被撲滅了！你和你的救火隊勝利了！呀哈！$B$B無頭騎士的攻擊失敗了，但除非他和他的頭一起被消滅，他還會再回來的。$B$B在此之前，讓我們好好享受你為這些孩子們帶來的安全吧。我很榮幸能目睹你今天勇敢的行為。',0);
