INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11222,'zhTW','所以這個詭計是迪菲亞兄弟會替奧妮克希亞做的？$B$B<國王的臉因為憤怒而漲紅，雙手緊握成拳。>$B$B你和普羅德摩爾女士為暴風城立了一件大功。這些叛徒死前甚至不會有時間後悔自己所犯下的罪刑。',0);
