INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11223,'zhTW','這真是天大的好訊息！我原本擔心大領主會質疑我們訊息的正確性，但現在看來是我多慮了。$B$B你將在塞拉摩和聯盟的名義下受到優渥的獎賞。',0);
