INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11227,'zhTW','你獵了幾隻烏鴉呢，$G小夥子:小姑娘？$B$B好狗兒，好狗兒！$B$B喔，這些獵犬讓我想起來我在提瑞斯法飼養純種犬的日子……那真是一段美好時光！',0);
