INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11228,'zhTW','那個矮人說的是真的。我們不能失去這個港口。這是聯盟在這片冰寒地獄中唯二安全的港口之一——另一個在西邊幾百裡外的北風凍原海岸。',0);
