INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11231,'zhTW','聖光祝福你，孩子！有了你的幫助，聖光甚至能照亮最黑暗的角落。$B$B拜託，收下這個以補償你的善行義舉。我可以看見你所釋放的那些人獲救。起碼，那些真的與聖光和聯盟同在的人，都回到這座要塞了。',0);
