INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11236,'zhTW','<上尉鬆了一口氣。>$B$B很好，這樣減輕了我們的一些壓力。$B$B$N，你又一次證明了你對西部衛戍要塞和聯盟的價值。從財寶庫中挑選一些吧，$g小夥子:小姑娘！這是我們起碼能做的！',0);
