INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11238,'zhTW','哇喔，那個號角真是冷啊！$B$B你再一次的拯救了西部衛戍要塞免於毀滅。你真是個令人感到好奇的$g男人:女人，$N。你這樣的人要是再多幾個就好了。$B$B哎呀，這一定要受到獎賞的。你喜歡哪一樣啊？',0);
