INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11239,'zhTW','<神父靜默地為你禱唸祝願。>$B$B祝福你，$N，你回應了我的祈禱。驕傲的立於聖光中，光榮的瞭解到你的行為非常的神聖！$B$B我相信教堂的保險箱裡一定可以提供某些你用得到的東西。',0);
