INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11240,'zhTW','<這個工兵咕噥著，像是他希望你沒有成功一樣。>$B$B上尉聽到你成功了一定會很開心。$B$B你知道，由於你是如此積極解決低語峽谷的事務，你何不就從這些當中挑一個去？',0);
