INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11244,'zhTW','維庫人對我們斥候所做的行為既殘酷又野蠻。這是一種恐嚇戰術，想要削弱我們的決心……想讓我們怕得四處逃命。$B$B它們失敗了。$B$B我們要讓這些混蛋瞧瞧和聯盟開戰會怎樣！',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 11245 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11245,'zhTW','標記得好，$g先生:小姐！不過我得記得請後方要塞的火炮手喝酒啊。',0);
