INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11246,'zhTW','嗯，$g先生:女士，我得說你做那項工作的時候有點太過投入了。$B$B<軍士小心翼翼地看著你。>$B$B總之，如果你不介意，我要拿回我的彎刀了。它雖然有點鈍了，不過我也不想你意外滑跤然後把我也給砍了。',0);
