INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11307,'zhTW','瘟疫沒有摧毀我們的目標？你確定，$N？！$B$B這一定是有什麼外在因素我們沒有想到到的……也許是氣溫過低？也許是……這個菌株的變質！',0);
