INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11311,'zhTW','元素生物的影響開始褪去，但它們還是會回來。我們已經爭取了足夠的時間，讓我們得以完成在此地的任務並且離開。',0);
