INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11318,'zhTW','幹得漂亮！要學會怎麼操控你的山羊得花上不少時間。當你一旦做到，你就會希望每隻山羊都是競速山羊。$B$B你說什麼？“我的報酬在哪裡？”哈哈哈……你得試試最快的山羊！你想要更多？那這樣如何……$B$B你贏得了替美酒節服務的權力，那邊有許多事情可做，有許多的報酬。尤其是對一個年輕急躁的山羊賽手。',0);
