INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11321,'zhTW','噢，只是張酒杯兌換券……說不定你還花了一番力氣才弄來。好吧，這是你今年的酒杯。$B$B不過我猜我應該還會常常再看到你。無論如何，要是想兌換美酒節獎卷，你找我就對了……$B$B或他找我……$B$B噢噢喔……或是他……',0);
