INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11324,'zhTW','迦瓦爾絕對不是座狼！我很瞭解這些生物……他們是狼人。$B$B不過，烏爾芬說它是從灰白之丘南下而來的？怪了，那兒可沒有什麼狼人才對。$B$B我非常感謝你幫助烏爾芬重返它在狼群中的地位。終於，我們能高枕無憂了。$B$B感激不盡，請你一定要收下這份謝禮。',0);
