INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11325,'zhTW','你看起來，聞起來都不一樣……你不是我的狼群中的一員。跟我說你的故事；我被困在這裡什麼也沒有，但我有的是時間。',0);
