INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11326,'zhTW','迦瓦爾絕對不是座狼！根據你的形容，聽起來更像是狼人！$B$B不過，烏爾芬說他是從南方的灰白之丘過來的？奇怪了，那邊可沒有什麼狼人才對。$B$B我非常感謝你幫助烏爾芬重返它在狼群中的地位。終於，我能高枕無憂了。$B$B感激不盡，請你一定要收下這份謝禮。',0);
