INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11327,'zhTW','天啊……這是什麼鬼？！看看這些東西！$B$B我們要立刻把這東西送回要塞，刻不容緩！',0);
