INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11331,'zhTW','嗯，$N，現在情況怎樣？$B$B什麼？！一個被遺忘者的超級瘟疫隨時會將人溶解？$B$B你把我的維庫囚犯變成了軟泥？$B$B<上尉看起憤怒而沮喪，幾乎要嘔吐了。>$B$B好吧，我知道我們現在該怎麼辦。或者說，你！該怎麼辦！',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 11332 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11332,'zhTW','幹得好，$N，漂亮！$B$B<上尉看起來非常興奮而高興。>$B$B這樣可以讓那些沒用的被遺忘者少來惹我們！$B$B你為自己在我們的金庫中掙到了一些東西！',0);
