INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11333,'zhTW','雖然因為泡水而受損了一些，但應該還能用。$B$B<索拉留斯把手伸入袋子裡，掏出了一些造型奇怪的香。>$B$B現在把它們丟進火裡，然後吸入那些氣體！$B$B<索拉留斯把香丟進燃燒的薰香爐中。>$B$B<索拉留斯深吸了一口氣。他的身體也隨之顫抖起來。>$B$B什……什麼……這不可能……我不能……',0);
