INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11340,'zhTW','再也沒有比將入侵者從部落領土中驅逐更大的榮耀了。我們對你今日所援助我們軍隊的莫大勇氣致敬。',0);
