INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11344,'zhTW','維庫人生下的人類小孩？而伊米隆下令殺死所有的人類後裔？$B$B<索拉留斯沉默了一會兒。>$B$B雖然我很想否認在我眼前的事實，但我辦不到。人類的血脈並不像是探險者協會所說的那樣“消失的血緣連結”。那些維庫人就是“消失的血緣連結”。他們就是人類的祖先。',0);
