INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11346,'zhTW','<勘測員貝瓦爾翻閱著符文之書。>$B$B嗯嗯……內容實在太多了。我需要一點時間來閱讀，而且如果我們想要了解這些符文的話，我們就需要親自制作看看。',0);
