INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11347,'zhTW','感謝！我要給你一些郵票來感謝你的幫忙。你可以和貝爾碧談談用郵票來交換獎券。你給他越多郵票，她就會給你越多獎券。',0);
