INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11348,'zhTW','你能擊敗縛石者穆迪斯真是太好了，但鐵矮人不會輕易放棄的。$B$B我們在瞭解他們如何使用符文上獲得了很多進展。或許下一次我們遭遇他們時，我們的知識將會變成優勢。',0);
