INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11349,'zhTW','<貝瓦爾仔細地處理這些工具。>$B$B我要來試用這些工具。如果我們想要了解鐵矮人的動機並打敗他們，我就需要了解符文確實的功用。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 11350 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11350,'zhTW','<遠行者翻閱著符文之書。>$B$B我雖然不是博學大師，但我對鐵矮人的語言還算熟悉。我猜他們刻在巨人身上的符文是來自於他們日常的用語，雖然有些許的不同。',0);
