INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11352,'zhTW','你能擊敗縛石者穆迪斯真是太好了，但鐵矮人不會輕易放棄的。$B$B當我的族人往北，我很確信我們會再次遭遇鐵矮人。下一次，我們會在他們開始之前就先打敗他們。',0);
