INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11356,'zhTW','你來這裡拜訪這些孩子！太好了！她們小小的生命中已經感受過太多悲苦。能夠看到一個像你這樣的真正英雄，真是太好了。這一定能夠振奮他們的精神！',0);
