INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11357,'zhTW','孩子們喜歡看到投入於工作的英雄。我希望有一天，這些孤兒都能成為部落中的有力成員，然後在光榮的戰役中力戰而死！$B$B啊，想到這樣高尚的命運就讓我忍不住想掉淚……',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 11358 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11358,'zhTW','<艾德蘭聽你敘述你的發現。>$B$B原來如此！麥加利斯一定是那些鐵矮人計劃的核心。我們一定要在計劃實現之前摧毀它！',0);
