INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11365,'zhTW','<先知聽你講述著發現。>$B$B象徵“北方”與“西方”的符文反覆出現？這表示有個強大的命令他們往那個方向移動，符文不只是推力，是某種東西吸引著他們，那是什麼呢？',0);
