INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11366,'zhTW','<先知厄丹聽你敘述發現。>$B$B麥加利斯？一份石板的文字翻譯！這個麥加利斯一定是那些鐵傢伙神秘計劃的核心。',0);
