INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11368,'zhTW','現在我才覺得可惜，沒有叫你順便把另外兩顆心臟一起帶回來。也許下一次吧。不管如何，你得贏得了你的獎賞。$B$B明天再來找我吧，我還有別的任務要託付給你。',0);
