INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11369,'zhTW','可以從蛋中感受到生命的脈動並不稀奇？我最好趕快把蛋送去給買家。我們可不希望它在這裡孵化，對吧？$B$B你的酬勞已經準備好了。$B$B明天再來找我吧，我還有別的任務要託付給你。',0);
