INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11370,'zhTW','嗯，我怕我的顧客沒有足夠的時間把整本書看完了。不過，這不是我們該擔心的事情。這是你的酬勞。$B$B明天再來找我，我還有別的任務要託付給你。',0);
