INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11372,'zhTW','我相信這些羽毛一定可以替酋長的頭飾增色不少。你已經贏得了你的酬勞，$C。$B$B明天再來找我，我還有別的任務要託付給你。',0);
