INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11373,'zhTW','<你可以感覺到風之貿易者獲得了很大的滿足。>$B$B很好，我很高興聽到他死去的訊息。或許我能自己解開他護符的秘密。不然，我也可以把它賣個好價錢。$B$B我相信這樣的報酬應該很適當。$B$B明天再來找我，我還別的任務要託付給你。',0);
