INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11374,'zhTW','你真是個$g英雄:女英雄，$N。我相信我的顧客應該可以找到辦法來釋放寶石中他們所愛的人。這真是一次傑出的工作，你的酬勞已經準備好了。$B$B明天再來找我，我還有別的任務要託付給你。',0);
