INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11375,'zhTW','我還擔心你回不來了。我想你應該沒有因為和摩摩爾戰鬥而聾了？$B$B這是你的獎賞。毫無疑問教授一定會很高興的，雖然我有點擔心他要拿這東西做什麼。$B$B明天再來吧，我還有別的任務要你幫忙。',0);
