INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11377,'zhTW','噢，我真的聞到美味的食物了！我希望你好好揍了一頓那些臭鳥。$B$B別客氣，自己拿一些多的。我相信你的才能一定可以派上好用場的。',0);
