INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11378,'zhTW','你安然回到了現在的時空。$B$B<風之貿易者四處張望。>$B$B看來並沒有什麼事情改變。但我又怎麼會知道是否發生過改變呢？$B$B這一刀斬得利落，我的顧客會很高興的。這是你的賞金。$B$B明天再來吧，我還有別的任務要託付給你。',0);
