INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11379,'zhTW','看看這樣東西……$B$B<洛克嚐了一口這道混合的菜餚，他的臉呈現出一種既痛快又開心的奇特表情。>$B$B我的阿達爾啊，這味道真棒！像你這麼有潛力的廚師應該隨時都帶著烹飪的材料。從我儲備的材料中拿走一些吧，我以你為榮。',0);
