INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11380,'zhTW','這些可是我見過的過最多汁的魔法莓了，光是瞧著它們就讓我變聰明瞭。$B$B看來我不太需要那些魚肉的存貨了，那就送你一些？相信你一定可以做出一些美味的料理。',0);
