INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11382,'zhTW','這裡面的沙子還往上流，真是詭異。我想我最好還是儘快把東西交給它新的主人。$B$B我感謝你完成了這個困難的工作，$C。$B$B明天再來找我，我還有別的任務要託付給你。',0);
