INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11384,'zhTW','哇，你拿到了！它好細小。不過，等那些德魯伊完成了他們的計劃——我聽說得花上非常久的時間——遷躍扭木就會重新長成。$B$B這是先前答應的酬勞。$B$B明天再來找我，我還有別的任務要託付給你。',0);
