INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11385,'zhTW','現在他們全都死去了，再也沒有導魔師了。透過虛空低語者獲得了滿足，你可以領取你的賞金了。$B$B明天再來找我吧，風將再一次向瑪哈杜恩輕聲低訴……',0);
