INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11386,'zhTW','我打算把這個東西自己留下來，然後把錢退給我的客戶。這一定能夠大大拓展我的生意範圍。$B$B<風之貿易者嘆氣。>$B$B但是我得維持我的聲譽。$B$B說到我的聲譽，感謝你幫忙維持它。這是你的酬勞。$B$B明天再來找我，我還別的任務要託付給你。',0);
