INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11388,'zhTW','我可不敢碰那個卷軸，說不定會引起上古諸神的注意，太冒險了。我會讓我的助手把東西送出去。$B$B你不只是賺得你的賞金，$C，我祝福你在所有已知的世界中都福星高照。$B$B明天再來找我，我還有別的任務要託付給你。',0);
