INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11457,'zhTW','你再度證明了你身為盟友的價值，$N。我們永遠不會忘記你的義行。',0);
