INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11459,'zhTW','塞吉說的話，你一個字都聽不懂？嗯，那可不嘛。$B$B讓我來給你說一下吧。',0);
