INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11467,'zhTW','我要拿走黃金，這是康納德欠我的。剩下你可以留著。$B$B如果你需要一點更保值的東西，我敢保證我能替你安排一些。願你的航行風吹不息，朋友。',0);
