INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11475,'zhTW','現在我拿到了我的工具，可以開始動工了。喔，只要我有材料的話。你接下來要幫我取得那些材料。',0);
