INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11479,'zhTW','這真是個難過的訊息。丹是我的老朋友……而且他還欠我錢！不管怎樣，如果他替那些南海的雜種工作，那他就是活該。$B$B而你，我的朋友。你現在可要一帆風順了。',0);
