INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11486,'zhTW','所以你去找了黑鐵矮人，以為可以阻止他們的破壞？他們不久前才又發動一次攻擊。看來黑鐵的承諾就跟他們的啤酒一樣可靠，嗯？$B$B不過你還是幫了忙。這是一杯你從山裡頭帶出來的“麥芽酒”，就當成是報酬吧。打敗那些黑鐵矮人想必也讓你渴了！',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 11487 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11487,'zhTW','所以你去找了黑鐵矮人，以為可以阻止他們的破壞？他們不久前才又發動一次攻擊。看來黑鐵的承諾就跟他們的啤酒一樣可靠，嗯？$B$B不過我猜想你還是幫了忙。這是一杯你從山裡頭帶出來的“麥芽酒”，就當成是報酬吧。別推辭，這起碼是我能做的。',0);
