INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11490,'zhTW','我認為我們今天的交會並非巧合。$B$B我可以感應到命運的交纏……',0);
