INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11491,'zhTW','你證明給他看了！該是讓你正式上場了。$B$B要有信心，我希望啦……',0);
