INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11492,'zhTW','<雷索爾專心地聽著你在魔導師平臺的壯舉。>$B$B塔雷斯將被懷念——他是個好人。感謝你，好讓他的死不會白費。$B$B我低估你了，$r。請你接受這樣禮物，來表揚你對太陽之井進攻部隊的貢獻——像你這樣的英雄才值得的禮物。',0);
