INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11504,'zhTW','<奧弗斯鬢胡豎了起來。>$B$B海盜……他們的邪惡是沒有盡頭的嗎？$B$B我們一定得找回這些被偷走的神器，並將東西還回這個被詛咒的地方，這樣我的族人們才可以重獲平靜。',0);
