INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11505,'zhTW','靈魂們只差一步就能平靜地安息。能獲得它們的眷顧是件好事，尤其是我們得在離它們安息之地如此靠近的地方掀起戰爭。',0);
