INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11506,'zhTW','靈魂們只差一步就能平靜地安息，並且賜予我們他們的眷顧。$B$B儘管這只是暫時的，但依舊能給予我們的敵人羞辱的一擊，他們的祖先居然反過來與他們為敵。',0);
