INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11550,'zhTW','基爾加丹挾著燃燒軍團的全部力量逼近這個世界。要是召喚儀式完成，我們的世界會再次陷入混沌的痛苦掙扎中。你在奎爾丹納斯島的協助將會是我們對抗燃燒軍團的關鍵。$B$B我們的法師正在努力穿透太陽之井的屏障。盡力幫助破碎殘陽來對抗燃燒軍團吧。',0);
