INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11564,'zhTW','喔耶，這些應該很夠用。$B$B就把它們隨便找個地方放著吧。你可以拿走一些我昨晚剩下的燉肉。',0);
