INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11568,'zhTW','真是壞透了的訊息，$N。我的人民正處在危險之中，他們要知道這個訊息——那些來自海上的怪物將不會對卡魯亞克手下留情。',0);
