INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11570,'zhTW','這個訊息真是太好了！你剛才說嚕呱吧呱發現了從洞穴瀰漫出的東西正是造成瘋狂的原因？$B$B那肯定是考達拉的魔法越來越強大了。魔樞之戰……那是一場藍龍軍團與其餘龍族之間的戰爭，屍橫遍野。$B$B很快，我們全都會被牽扯進去的！',0);
