INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11614,'zhTW','情況比死還嚴重……很怪的是，蛛魔並沒有吃掉屍體。$B$B在一陣小心的檢驗後，你發現盧瑟的死是自己造成的——致命的毒藥。很聰明。這樣蛛魔就不會接近這個中毒的屍體。$B$B你注意到盧瑟手中握著一本日誌。',0);
