INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11628,'zhTW','儘管我討厭把這些東西帶回村子裡來，但我們可以利用它來對付我們的敵人。$B$B<酋長對先知埃恩雷做了一個手勢，然後揮揮手讓人將猛獁皮拿下去。>$B$B在她處理毛皮的時候，我們還需要另一樣東西來製成隱匿披風。',0);
