INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11629,'zhTW','因波莉安把她自己的元神精華給了你？我可以聽到她的哭號的風聲了！$B$B我知道一種儀式，可以好好利用它。在她的元神精華開始斑駁以前，我們得加快腳步！',0);
