INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11630,'zhTW','<冬風酋長謹慎地收下你收集到的土壤。>$B$B我們要儘快把這些交到先知埃恩雷的手上。$B$B<酋長咕噥著，好像沒有受到那些疫病土壤的干擾。>$B$B我們永遠也不知道天災軍團的指揮官什麼時候會對村子發動最後的攻擊。',0);
