INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11631,'zhTW','他們束縛了他的靈魂，$N，我們必須將他的折磨作個結束！$B$B你一定要深入獁格莫斯，找到方法釋放他！',0);
