INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11633,'zhTW','<冬風酋長傾聽著你的彙報。>$B$B你所收集的情報對我們突襲聖城的計劃很有幫助。我們得找出方法擊敗你發現的首腦並攻進大墓地。',0);
