INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11634,'zhTW','是，老兄。我正等著你。$B$B<託波爾指著西方。>$B$B看一眼。越過了那片凍土荒原就是死亡，老兄……死亡。',0);
