INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11636,'zhTW','對那些死人不需要留情！$B$B在地獄咆哮將這片海岸認定為“受詛咒的”之後，就沒一個傢伙有膽留下來保護我們光榮的坦克。最近這裡都很平靜，看著天災軍團如何一步步提高對戰歌堡的攻擊。有時候會有個迷路的殭屍或食屍鬼，但他們都撐不了太久。$B$B<寇治敲了敲他的斧頭。>$B$B當然，這裡還有迷霧……$B$B<寇治鬆了聳肩。>',0);
