INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11638,'zhTW','感謝你從卡加尼舒手上解放了他的靈魂，並將他的遺骸拿回來。我們沒有什麼能獎賞你的，如果有什麼你中意的就拿去吧。$B$B那麼現在，我要將他迴歸到他所該去的地方。',0);
