INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11639,'zhTW','你的行為榮耀了死者，$N。$B$B<受傷的獸人點頭並慢慢的吐出一口氣。>$B$B或許現在我能再次成為一名戰士，如同過去的我一樣。',0);
