INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11650,'zhTW','很好，這才像話！現在我們該做的就是將這些東西組合在一起。$B$B沒錯，你即將幫我把那東西完成。$B$B拉住你的馬匹，既然我都已經拿回我的工具了，這只需要一會兒就好了！',0);
