INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11651,'zhTW','以我們當前的交通和航線狀態來看，我們連運送一具該死的攻城機具來戰歌都沒有辦法。當前我們手邊的這些坦克是原來的遠征隊遺留下來的。既然東西還可以用，你就用它們來重創納森平原的天災軍團進攻部隊吧。',0);
