INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11652,'zhTW','克爾蘇加德？所以這是真的了——納克薩瑪斯回來了……$B$B也許我低估了你，$N。你替部落做出了一個重大的貢獻。大酋長會感到驕傲的！$B$B<加爾魯什停下來想了想。>$B$B如果說克爾蘇加德控制著這些天災軍團，誰知道巫妖王還替我們準備了哪些驚喜……我需要一點時間消化這個新訊息，$N。你可以走了。',0);
