INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11889,'zhTW','它們從地上來我們會擊敗它們，它們從空中來我們也會給它們好看。如果那些沒爹沒孃的不死生物敢從海上來，我們絕對讓它們沒命回去。',0);
