INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11890,'zhTW','真是個糟糕的訊息。$B$B我的族人很快就要離開這個地方了。我們要衝破天災軍團的防線轉至我們在龍骨荒野的家園——冰霧村。$B$B但在此之前，我們要解決侏儒的瘋狂所造成的災害。',0);
