INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11892,'zhTW','唉，奈辛瓦里走了，也許他從來就沒在這裡……$B$B<伊拉索留斯嘆了口氣。>$B$B這惡魔很狡猾，但是他的時日不多了。我們會把他揪出來的，一定會……',0);
