INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11896,'zhTW','隨著他們的機器爪牙被解決，就該是我們進行更大犧牲的時候了。不幸的是，儘管如此，我還是能感覺到風暴之力在你體內逐漸散去。$B$B不過，這符合它的目的，我想就算沒有這東西，你還是有辦法進行下一步。',0);
