INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11897,'zhTW','做得非常好，$N。沒有你，無畏要塞也許無法抵擋得住敵人。謝謝你的協助，我們將會繼續戰鬥下去。',0);
