INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11900,'zhTW','這比我預期的還糟糕。$B$B瑪裡苟斯引導太多力量到這個地方了。如果再不阻止他，艾澤拉斯將會成為另一個外域！$B$B幸好，我相信我找到了一個臨時的解決方法……',0);
