INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11902,'zhTW','那些可憐的小夥子……他們根本沒有機會！$B$B這聽起來就像是內奸乾的。說不定是個詛咒教派的滲透者。那些瘋子最好都下地獄去！',0);
