INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11906,'zhTW','在我們繼續旅程之前，我們把土地復原，這就是犛牛人的傳統。$B$B我們很快就要出發轉至我們的首都——冰霧村。你的幫助讓我們的速度提高了不少。$B$B感謝你。',0);
