INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11911,'zhTW','太驚人了！$B$B你說，他們也很具有侵略性。這表示有某些勢力在幕後操控。這並非自然的現象……$B$B拜託，$N，接受這個象徵我們對你的感謝。達拉然將會為你效力。',0);
