INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11916,'zhTW','我怕你來得太晚了，勇士。我們許多的兄弟姐妹已經拋棄了犛牛村，轉至龍骨荒野，在遙遠的東方尋找庇護。$B$B這裡留下了許多等待完成的工作，卻很少人願意協助我們……',0);
