INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11917,'zhTW','你做得很好。這也許看來是很小的一步，但對大局來說卻可以做為戰鬥的支援。收下這個和我的祝福，稍晚點來也許我會有更多事要讓你去做。',0);
