INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11938,'zhTW','這應該可以為我們爭取一些時間。伊斯多魯斯很合作，但我真的需要和這個巫妖單獨相處一下。',0);
