INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11940,'zhTW','不需要為了這些年幼雛龍的命運感到良心不安，$r。瑪裡苟斯才應該要為此負責。$B$B我努力不懈地研究想揭開這些符文的奧秘。$B$B我向你保證，除非必要我們不會再奪取更多的生命了。',0);
