INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11941,'zhTW','你把這個帶來給我是明智的，$N。$B$B<萊洛拉斯看著碎片並且緩緩點頭。>$B$B如果你真的願意做出貢獻，那麼不管風險有多少，我都應該和你分享它的意義。',0);
