INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11944,'zhTW','那樣應該會為我們爭取到一些時間。$N。我們還抱著一線希望，希望會有來自無畏要塞的援軍抵達。',0);
