INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11951,'zhTW','感謝你，$N。$B$B我在被拘禁的期間耗盡了氣力，而我的力量也從來沒有恢復得這麼緩慢過。$B$B我得謹慎地使用這些水晶的力量。它們是瑪裡苟斯邪惡計劃的副產品。幸運的話，它們或許還能在瑪裡苟斯的毀滅上貢獻一份力量。',0);
