INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11957,'zhTW','現在沒有了莎拉苟薩，這個世界又改善了一些，但我們的工作還沒有結束。$B$B現在是時候對付瑪裡苟斯本人了！',0);
