INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11958,'zhTW','拜託你為我們做這種事情很讓我過意不去，但為了儘快完成我們的遠行，這是我們唯一能做的。雖然要去哪裡，我們現在還不知道。$B$B我的巫士們告訴我，你就是要從暗影行者手中拯救這片土地的人。$B$B我同樣相信，你會拯救這片土地上的人們。',0);
