INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11959,'zhTW','洛根被殺掉，正是我的族人所需要的，而我們會令其它的狼獾人爭奪他的位置。$B$B這樣就足夠了。',0);
