INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11960,'zhTW','很好，我想你應該拯救了不少。感謝你，$r。$B$B現在狼獾人有機會我們一起存活下來了。當然，如果我們能倖存的話。$B$B你明天可以再回來一趟，好讓更多幼崽獲救嗎？',0);
