INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11972,'zhTW','的確，這些裂片蘊含著冰霜之王在這塊土地上最後的精華。我們會處理它，把埃霍恩放逐到冰冷的虛空國度。$B$B感謝你，$N。你的名字將被大地之環永遠傳頌。如果你收下這點東西會是我們的榮幸，這象徵了你的仁慈、溫暖與光明。',0);
