INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11984,'zhTW','做得好哇，$C。看來我們可以讓巴德在這多待久一點。$B$B我們馬上就把你的籠子處理好，這是你的賞金。$B$B喔，歡迎來到營地，多逛逛，我相信我們能合作愉快的……',0);
