INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11989,'zhTW','啊哈！$B$B現在我們透過血而相連了，老兄。我們有了真正的羈絆。$B$B你仔細聽達庫魯的，$r，我們有很多事情得做。',0);
