INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11990,'zhTW','<達庫魯將材料熟練地混合在一起並且放入瓶中。>$B$B這樣應該可以了，老兄。工作的時候到了。',0);
