INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11991,'zhTW','啊，是的。你做得很好，老兄。$B$B我可以從這片牆上開始讀……',0);
