INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11992,'zhTW','塔尤卡在上！這些怪物計劃要攻打卡瑪古！$B$B我們要確保他們絕對不會成功。如果我的同胞獲得事先警告，他們一定多數能獲救。我很感謝你的訊息，$N。',0);
