INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11993,'zhTW','<托爾森聽你解說符文板上的內容。>$B$B瑪多蘭的錘子啊，他找到了一個新的泰坦城市！$B$B石頭與鋼鐵的發源地。$B$B“奧杜爾座落於風暴之中。”$B$B你知道那是什麼意思嗎？那裡可能就是我們的起源故鄉，在這麼多年之後？$B$B我們得跟著他！我們得找到他！',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 11995 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11995,'zhTW','我正在等著你，$C。我們有很多工作等著你和我一起進行。',0);
