INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (11999,'zhTW','有意思，他們想要和虛靈復仇軍合作。對於瑪裡苟斯和他的瘋狂而言，虛靈確實是個強力的盟友。$B$B這樣可不行！',0);
