INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12002,'zhTW','<布魯加爾聽著你的回報。>$B$B聽起來事情似乎和緩了一些。我們會開始尋找進入鐵矮人隧道系統的方法。',0);
