INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12003,'zhTW','<布魯加爾啐了一聲，以矮人語咒罵著。>$B$B沒有入口？沒有？$B$B不，這當然不可能太容易。嗯，看來想盡入城市是免不了一場戰鬥。我的手下再也沒辦法進行真正的工作。',0);
