INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12005,'zhTW','這樣就好，$C，就把他們放在阿格瑪的王座前。$B$B<你幾乎可以感覺到大法師在頭盔下的笑容。>$B$B可惜古拉莫什指出協議已經達成了。$B$B但不管怎樣，終究是少了兩只需要煩心的蟲子。讓我們來進行更重要的事情吧。',0);
