INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12022,'zhTW','你知道那是什麼嗎？侏儒工程學的最高傑作！S·T·O·U·T·能像個鬥士般耐打！$B$B我認為你現在已經準備好應付那些黑鐵矮人，如果那些傢伙再次出現的話。',0);
