INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12026,'zhTW','這個布萊恩·銅鬚是誰？鐵矮人沒理由要和他交涉，我也不知道為什麼要對他寫的文字感興趣。',0);
