INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12027,'zhTW','感謝老天讓你找到了艾米莉！當她一個人離開的時候，我就擔心她會迷路了。$B$B我也很高興知道小毛球安然無恙。',0);
