INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12030,'zhTW','我一直期待你的到來，$r。我看到你的靈魂飛過，感受到秘法師藉由你的雙眼觀察世界。$B$B你和卡魯亞克的命運，如今緊緊相系。',0);
