INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12036,'zhTW','那個該死的深淵一定是直接通往艾卓-尼魯布。這比我想得還糟糕。$B$B<祖托克停下來想了想。>$B$B搜尋並摧毀……這將會是下一步的行動。',0);
