INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12037,'zhTW','我就知道！$B$B就算我鬧失蹤也不可能讓那些沒骨氣的黃鼠狼出來找我。$B$B好吧，他們派了你。我想這也算是……$B$B嗯，拿著這個。我寧可把東西交給你，也不要給營地裡的那些蠢蛋。',0);
