INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12039,'zhTW','這麼輕……幾乎沒有什麼重量！我要開始分析這種金屬，看看能不能用它來製造點什麼！實驗！要儘快開始實驗！$B$B我會和你保持聯絡，$N。要是我有什麼成果，我一定第一個通知你。',0);
