INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12058,'zhTW','<當你回想著石板上的翻譯時，先知帕魯納聆聽著。>$B$B這麼說，布萊恩覺得他找到了一座新的泰坦之城？$B$B“奧杜爾座落於風暴之中。”$B$B我會請求酋長派遣遠行者到風暴峭壁去。我的族人很清楚這些地方，很有機會能查出這個難以捉摸的矮人下落。',0);
