INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12060,'zhTW','照你的描述……那是奧法之圖投影！$B$B<大法師焦慮的神情馬上就被他冷酷的外表給掩飾住了。>$B$B奧法之圖是世界上所有魔網能量交匯點的地圖。藍龍軍團利用它尋找並摧毀地脈“焦點”，以便把魔網能量送回魔樞。$B$B問題是，送回的路徑應該是通往西方，但是為何是往東方呢？',0);
