INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12123,'zhTW','能將這個訊息帶給我們需要莫大的勇氣。我一直在懷疑藍龍軍團為什麼如此大膽地對神殿發動攻擊。如今我知道了，他們大量使用那些原本藍龍軍團視為對造成艾澤拉斯巨大威脅的魔法。$B$B<紅龍女王無可奈何地搖了搖頭。>$B$B哎，但是不能任由它們胡來。如果瑪裡苟斯不能恢復理智，我們除了對他的進犯進行反擊之外別無他法。',0);
