INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12132,'zhTW','$N，我為我所持有的力量付出過巨大的代價。許多騎士——不論是神聖或黑暗——在聖光之願禮拜堂的決戰中喪生。雖然未來的景象是如此險惡，但我知道我終將面對的是什麼。巫妖王永遠不會放開他的魔爪，也因為如此，他必須死！',0);
