INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12150,'zhTW','“雷霆使者”戈洛塔爾。很好。現在就讓我們來解決猛獁人對此地造成的威脅。',0);
