INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12151,'zhTW','你實在可敬可畏。$B$B只要“雷霆使者”戈洛塔爾不在了，我們就可以不管其餘的猛獁人，讓他們彼此互相鬥爭，把我們的注意力轉回更嚴重的威脅上。$B$B令人佩服的成就，$C。',0);
