INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12152,'zhTW','完成了。$B$B你的無私帶給許多靈魂永恆的平靜，終結了亙古的磨難。$B$B願此舉能照耀你的靈魂，減輕你的重擔，因為我的眼中仍可見你必須面對更大的危機。$B$B再會吧，$N。',0);
