INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12153,'zhTW','真的成功了？$B$B<萊加爾·斷眉清了清他的喉嚨。>$B$B我是說……當然會成功啦！真是難以置信！$B$B今後，$N，探險者協會的新成員便能聽到了萊加爾·斷眉的故事，以及隨便一尊破銅爛鐵魔像就打敗了丹厄古爾的鐵領主！',0);
