INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12157,'zhTW','當我透過橋進入龍骨荒野的時候，我被一小隊的阿努巴爾蟲族偷襲！我被團團圍住！那些怪物知道我會來。遍體鱗傷的我差點逃不出來。我握有的這份名單一定要被送往暮冬要塞，可是，我傷得太重了，根本不能過去。',0);
