INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12160,'zhTW','運氣真背。我們好不容易在山的這一面找到可以運作的礦洞，卻滿是天災軍團。$B$B沒有惡意，我的朋友，但是你所發現的這些倖存者，因為失去朋友而發瘋了。阿魯高死很久了……我真的看過他的墳墓。',0);
