INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12185,'zhTW','也許洛肯並沒有誇大其詞？泰坦的石巨人族和鐵矮人族子嗣竟然為了奧杜爾的控制權打得不可開交。這太瘋狂了，$N，這有可能會把我們得知矮人族歷史的唯一機會給毀了！',0);
