INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12188,'zhTW','這些就夠了，$N。這些可悲的蠢貨有試著攻擊你呢，還是純粹對你噴灑著悲苦的鬼魂之淚呢？$B$B啊，他們實在很情緒化……',0);
