INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12189,'zhTW','我們遇到了一個小小的——微不足道的——問題。每個試著要碰凋零藥劑的人都蒸發了。我們企圖些微調整這個配方，好讓你不會只是在路邊看它一眼你就爆了。好訊息是，我就快要想出來了！',0);
