INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12190,'zhTW','很好！好心的老普雷蒙讓你把東西送來我這？$B$B有了這些，就能弄一頓好吃的啦。只要再來幾樣東西……',0);
