INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12191,'zhTW','哇……S·T·O·U·T·沒有壞掉……嗯……誰想得到？$B$B我的意思是，嗯，你辦到了！你的準頭不賴，起碼夠保護這個營地了。我想你已經準備好對付那些黑鐵矮人，要是他們膽敢再出現的話。',0);
