INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12196,'zhTW','<羅卡爾用他的手背擦了自己的額頭。>$B$B喔，感激聖光。他威脅我說在你回來之前都不給我東西吃。我們來整理一下這堆零件，看看能做出什麼。',0);
