INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12203,'zhTW','他是說要挑起泰坦創生種族勢力間的內戰？為什麼泰坦城市奧杜爾對他如此重要？我猜這就是庫倫和他的巨人所希望阻止的。$B$B我想我們正好處在一個可以阻止巨人彼此征戰的位置上，但我們也可以找出方法來利用這個情況。我得馬上通知我們的首領。',0);
