INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12206,'zhTW','什麼鬼東西？！不可能！凋零藥劑的製作完美無瑕，它應該百分之百致命才對。$B$B<藥劑師薇吉·萊文搓著她的手，擔憂的表情滿布在那毫無生氣的臉上——顯然是受到了挫折——她用憤怒的口吻繼續道。>$B$B這真的是奇怪得很呢。瓶子給我，$C。我可不要讓人知道我是那個毀掉一切的藥劑師！',0);
