INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12224,'zhTW','為了部落！$N，久仰。你身上深刻的傷疤——正是你的力量與奉獻的試煉！$B$B部落先遣軍遭受到巫妖王東西兩面的夾擊，僅有天譴之門的軍力殘存了下來。不過我們每天都有新進展，馬上就能攻破高牆突入冰冠冰川！$B$B只要我們阻止了白骨巨龍和大領主弗塔根，我們就能奪下這塊區域了。',0);
