INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12232,'zhTW','快樂的一天！$B$B既沒佔用到藥劑師的時間和資源，就完成了這項任務，我相信這吸引了指揮官的注意力！$B$B不按牌理出牌，這就是我的做事態度。對，對啦，你也幫了點忙。$B$B來，如果我給你一些東西，能保證絕口不提你有參與此事嗎？',0);
