INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12251,'zhTW','<哈爾弗向你行禮。>$B$B村人全都回去工作了？傑出的表現，士兵！我們很快的就可以重建並強化城鎮的防守。我們很快的就可以準備好援軍增援弗塔根領主在天譴之門的戰鬥。$B$B當然，這話說的有點早了，在我們送你去幫伯瓦爾之前還有很多事情要做。',0);
