INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12252,'zhTW','他們知道了這麼多？還有，他說的那個見鬼的海軍上將韋斯溫到底是誰？！$B$B<執行官嘟囔著著說他討厭驚喜。>$B$B我們最好搞清楚，而不是在這裡瞎猜。我希望你有留下你的……呃，我的印記。',0);
