INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12253,'zhTW','<哈爾弗為染病的人唸了一段禱言。>$B$B你替聖光盡了一份力，$N，但是恐怕我們的工作才剛剛開始而已。$B$B<哈爾弗拿出一份檔案。>',0);
