INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12448,'zhTW','這個任務令人作嘔，但我為你的付出表示感激。$B$B天災軍團不能向龍殿外推進任何一步，否則這片大地都將失守。',0);
