INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12459,'zhTW','非常好。就跟我一直所猜測的一樣。我得試著和伊瑟拉聯絡，看看她是否允許。$B$B當然，如果能從她的惡夢中哄騙出來的話。$B$B感謝你，$N。你的存在不可或缺。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 12460 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12460,'zhTW','勞莉耶爾大使派你來的？$B$B如果你再見到她的話，請向她說我非常感激她的協助。我們有太多的戰線要維持了。',0);
