INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12476,'zhTW','希望對這些先鋒軍來說，我們的表達的訊息已經很清楚了。我希望這些攻擊行動足以讓他們懷疑是否要繼續加入那個組織。',0);
