INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12477,'zhTW','<哈爾弗閱讀著這本書。>$B$B阿比迪斯已經走火入魔了。聖光跟她說話？$B$B除了空洞的胡言亂語之外，這本日記讓我們一窺血色狂熱分子的內心。這是個重要的發現，$N，弗塔根大人會很開心的。',0);
