INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12489,'zhTW','哈哈！在叢林中可不是常常能遇到生人的，朋友！$B$B你是那些德魯伊雜碎派來“阻止我和我邪惡的行事方法”的，是嗎？那我提前祝他們好運啊！$B$B<赫米特露出一個興奮的笑容並輕拍他的槍。>$B$B我可一點都不覺得我“邪惡”！非常歡迎你加入我們的狩獵，我們很快就會解決掉那些風險投資公司的走狗。這邊還有很多事要做呢。',0);
