INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12491,'zhTW','這就是寇仁·恐酒的飲料？他急著想要在美酒節提交的酒？哎，官方無法認可這次的提交，不過出於對一位逝去釀酒者的尊敬，也許我會嘗一嘗……',0);
