INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12545,'zhTW','如你所見，天災軍團的戰爭機器不斷的往前逼近，而部落和聯盟的軍隊卻還是彼此分裂，正成了他們的犧牲品。這就是我們必須團結的理由。$B$B<瓦魯斯短暫地沉浸在冥想中。>$B$B銀色北伐軍用的著像你這樣的$g男人:女人，也許你有意願加入我們？在灰燼使者的身邊至死奮戰？',0);
