INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12592,'zhTW','哎呀，你已經要來認輸啦？$B$B<當你告訴德羅斯坦說你已經達成目標的時候，他張大了嘴巴。>$B$B不可能！以艾澤拉斯之名，你是怎麼辦到的？我才剛殺到第58只而已。就差那麼一點！$B$B但就事論事，是我低估了你，$N，而你光明正大地贏得了這場勝利。',0);
