INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12595,'zhTW','所以老赫米特總算沒把我給忘了。我猜他是打算等我把所有困難的工作都完成之後，再來參加這場狩獵。別擔心，這裡還有一大堆飛龍四處遊蕩。赫米特會得到他想要的。',0);
