INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12625,'zhTW','拉蘇維奧斯又替我們死亡騎士增加了一位成員？$B$B<科弗斯搓著他露出白骨的雙手。>$B$B太好了……強大的天災軍團很快就要席捲這片土地，將所有的生命化為塵埃！$B$B讓我們省略介紹，直接開始工作吧！',0);
