INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12634,'zhTW','唔，這比我預計的還要豐富許多。好吧，現在問題來了：我們能把它蒸餾成能喝的酒嗎？$B$B我們最好快點開始。',0);
