INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12635,'zhTW','噢，最高階的樣本！$B$B你可以看出這個分離形成了象徵學的根基。真是傑出。$B$B這些冰巨魔決定自我毀滅真是令人遺憾。$B$B舉例來說，你知道嗎，達卡萊巨魔是因為他們極度的暴力而被其它的巨魔國家流放？$B$B這是真的！不然你以為巨魔是怎麼會跑來這個氣候這麼嚴苛的地方呢？',0);
