INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12653,'zhTW','<獵豹女神痛苦的嚎叫。>$B$B我的靈魂因為再度失去一個朋友而哀嚎。但是不要害怕，他會回來，並且它的靈魂將永生不朽。',0);
