INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12655,'zhTW','<希姆魯克認同了你放在他面前的供品，即便他知道那是從別人的屍體上取來的。>$B$B<如果你將供品獻給他，他勉強同意賜予你祝福。>',0);
