INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12656,'zhTW','<希姆魯克在你心中灌入一個影像，他的守衛將你踩碎在腳底下。也許你該試著用更多祭品來討好希姆魯克。>',0);
