INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12658,'zhTW','噢，這些很棒！我已經厭倦了跟機械松鼠以及機械小雞作伴了。如果有隻關節不用上油的寵物一定很棒！',0);
