INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12659,'zhTW','哎呀，我覺得這真是太有趣了。$B$B$N簡直就是$r之中的我啊！$B$B你還拿著我的小刀吧？',0);
