INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12661,'zhTW','嗯，好吧……我承認我看到你還蠻驚訝的，$N。$B$B告訴我你得到的情報吧。',0);
