INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12665,'zhTW','謝謝你把我的小貓平安的帶回來。$B$B其實我心中早就知道了，只是不想不願去面對，但你的眼睛已經揭示了真相。$B$B然而，我還感覺到什麼別的東西。事情並不是表面看起來的那樣。',0);
