INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12669,'zhTW','做得好，$N！$B$B稀釋了那些大鍋，不但可以拯救生命，還會減緩這裡天災軍團的成長速度。$B$B現在過來這裡，告訴我你對達庫魯在祖達克的策略瞭解多少。',0);
