INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12670,'zhTW','你聞到了嗎？$B$B<瓦拉納王子嗅了嗅空氣。>$B$B新鮮的肉……血色十字軍的香味隨風飄來。$B$B<瓦拉納流下了口水。>$B$B抱歉，死亡騎士，我想你對我的美食觀念一定不感興趣。你是來工作的！來領導衝鋒的！是的……我知道。巫妖王已經把我該知道的都告訴我了，$N。$B$B讓他們血濺沙場的時刻已經到了。',0);
