INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12674,'zhTW','<你面前的恐怖靈魂發出了一陣令人脊背發冷的笑聲。>$B$B他們自找的。我還會再讓他們體驗同樣的事，一次又一次又一次又一次……',0);
