INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12675,'zhTW','我的部分精魄？$B$B<獵豹女神停下來想了一想。>$B$B這是非常過分的要求，尤其是為了復仇這樣的目的，況且我已經因為我的鎮壓者而變的非常虛弱。$B$B不過，我也許知道一個方法。',0);
