INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12677,'zhTW','好極了！$B$B我們將會立刻調查這些水晶的特性。$B$B現在告訴我，$N，達庫魯一夥人做了些什麼事？',0);
