INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12678,'zhTW','你感覺到了嗎，$N？那種感覺，就是在你體內流動的全新力量。凡人是體會不到這種感覺的。$B$B前線現在已經崩解了，魂屍將會完成剩下的工作，並且替拉蘇維奧斯準備好場地。我們則把注意力轉移到更具戰術性的目標上。',0);
