INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12680,'zhTW','接下來才是真正的試煉。你能夠對一頭不羈的戰騎展現出多少駕馭的本事，然後用蠻力奪取你最想要的東西呢？',0);
