INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12681,'zhTW','<考爾文一臉欽佩地看著你帶來的爪子。>$B$B這樣就夠了。伯塔魯斯的說法是爪子越扭曲多節，法力就越強。我想大法師為這個營地付出的金幣收回票價了。',0);
