INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12683,'zhTW','太棒了！這裡是說好的工資。還有，只是推薦一下：如果這種“燒灼感”持續不退的話，這幾天你可能要好好洗個熱水澡。',0);
