INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12685,'zhTW','<巫醫不可置信地搖了搖頭。>$B$B聽起來你十分驚險地從奎絲魯恩的靈魂界生還了。$B$B我很高興你去進行這個工作——我不知道我自己有沒有勇氣面對那種狀況！',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 12686 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12686,'zhTW','你做得很好，$N。你學習的速度比我想的還快。$B$B去吧，休息一下。我很快就會給你更大的考驗！',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 12687 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12687,'zhTW','你成功完成了大多數新兵辦不到的事情，$N。為此，你將會得到可觀的獎賞。$B$B<薩拉納爾鞠了個躬。>',0);
