INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12688,'zhTW','謝謝你救了赫莉絲，還陪她回來。她外出找水晶一直沒有回來，我們實在很擔心。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 12689 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12689,'zhTW','嗨！很高興再見到你！$B$B我知道我們是朋友。我就知道！你是好朋友。不只是我們的，也是所有神諭者的。$B$B我看到你跟那些小狗人很要好！不死的東西說你以前是他的朋友？我不知道。不過你跟小狗人絕交了，對吧？現在只跟神諭者當好朋友吧？$B$B等等！別隨便同意——你確定你不要跟小狗人當朋友了？',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 12690 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12690,'zhTW','做得好，老兄！$B$B我把酋長全都關起來了，而你帶領著我的憎惡打敗了他們的軍隊。$B$B該去慶祝一下了，老兄！',0);
