INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12691,'zhTW','巨型石鑰匙發出了一聲低沉的喀擦聲，然後石箱的蓋子開啟來，顯露出裡面隱藏的財寶。',0);
