INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12692,'zhTW','再次見到你真好。我知道你不是叛徒，我很高興瑟匹克證明了我是對的。$B$B我聽說你現在是巫妖獵手了——真棒！你讓哈爾卡克覺得很驕傲。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 12695 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12695,'zhTW','很高興又見到你！當你沒有馬上回來的時候我們有點擔心。$B$B亞魯烏特搶在你之前回來了——他精力充沛，跑得很快。他告訴我你從那個巫妖手中救了他。莫烏德也告訴我你怎麼拯救了苔行村。你真是個好人。$B$B我希望你在我們這兒待上一會兒。總是有事情要做。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 12696 AND `locale` = 'zhTW';
