INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12697,'zhTW','雖然你們經歷了千難萬險才來到收割者的領域……等等。$B$B<戈提克看了看他的筆記。>$B$B抱歉，$r。老習慣很難改。$B$B那麼，是瓦拉納派你來的咯？我相信你一定相當能幹。$B$B我確實有份禮物要給血色的雜種。這一定能讓他們加快在礦洞的工作。',0);
