INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12729,'zhTW','你的勇氣似乎是無限的，$N。$B$B請把精華交給我，然後我就會將它們製成能夠強迫先知出現在你面前的東西。',0);
