INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12730,'zhTW','你做到了！$N，你真是祖達克的勇士！$B$B我們永遠無法還清欠你的人情，但贊達拉巨魔把一些物品交託給我，相信你會有興趣的。$B$B我很希望你能瞭解並接受我們的感激之情。但現在我又有一件緊急事件必須處理。',0);
