INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12754,'zhTW','<奧爾巴茲閱讀了資訊。>$B$B壁爐谷和提瑞斯法的軍隊將會掉入大屠殺的陷阱之中。$B$B<奧爾巴茲微微一笑。>$B$B現在輪到計劃的第二部分了。你要把這個資訊送到大將軍阿比迪斯的手中。這就是那些衣服的用途……',0);
