INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12778,'zhTW','你做得很好，$N。天災軍團的印記已經烙印在這些血色大地中。你已經獲得超乎肉眼可及的死亡和毀滅，並將最後的血色軍隊帶來給我。$B$B<巫妖王指著海文郡的廢墟和燃燒中的新阿瓦隆城。>$B$B現在該是時候去結束你所引起的事情了。',0);
