INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12779,'zhTW','跪下，勇士。我以此盔替你加冕以鑄成你令人驚恐的形貌。任何膽敢窺探你黑暗面容的人終將明白死亡將至。別讓任何人膽敢反抗你的君主，因為他們得面對你絕不留情的憤怒，$N。$B$B現在只剩下最後的任務……$B$B<巫妖王看向了西方。>$B$B聖光之願禮拜堂。',0);
