INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12807,'zhTW','銀色北伐軍愚蠢地忽視血色先鋒軍的存在——我們可不會這麼做的。$B$B我們不指望他們能否在對抗巫妖王的戰爭中派上用場，我們不相信他們有資格存在。我們將會是他們的末日，將他們一次解決！',0);
