INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12809,'zhTW','不能想象的純淨！這個裝置儲存的聖光能量遠遠超過現在已經的任何東西！喔，這幾乎讓我的鬍鬚和腳指都在發抖了。喔哈！我可以用這個造出抗夜間影像分佈促動器，能讓黃昏變成黎明！天災軍團甚至不會知道什麼打中了他們。我們只要拉下拉桿就可以把他們一掃而空！',0);
