INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12820,'zhTW','於是……我就坐在這裡，沉浸在我自己的偉大之中，然後我聽到遠方傳來一聲——啪！然後又一聲——轟！再十幾聲！然後想到那些熱切奔向死亡的猛瑪象和狗頭人，我的臉上就浮現了一絲微笑。$B$B那是不是很精彩呀？',0);
