INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12839,'zhTW','韋斯溫寫的信箋？你為什麼不早講呢？$B$B<埃雷特從你手中把信搶去閱讀。>$B$B這個蠢蛋！他真的在這兒？！$B$B<高階指揮官大笑。>$B$B這是全新的情報。我很好奇他是如何幻想要在打倒巫妖王之後征服世界的呢？就算是他，也沒辦法在自己腦中完成這兩個瘋狂想象的任何一個吧。',0);
