INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12842,'zhTW','記住這些話，死亡騎士：符文熔爐是一種天災裝置。它只存在於阿徹魯斯、納克薩瑪斯、以及冰冠冰川的中心！你只能夠在符文熔爐銘刻你的武器。$B$B記得時常回來把你所有的武器刻上符文。一個死亡騎士必須準備好面對所有膽敢反抗$g他:她的東西！',0);
