INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12849,'zhTW','在指揮大廳裡，你會找到血魄、冰霜、與穢邪的學院。每個學院都有一個訓練師會提供你各種黑暗技藝的知識。$B$B我，索瓦爾領主，乃是血魄學院的院長。雅莉絲翠女士統領著穢邪學院，而大巫妖艾默薩札德，則支配著冰霜學院。$B$B當你獲得力量之後必得立刻回來這裡接受訓練！',0);
