INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12852,'zhTW','瑪爾加尼斯？！$B$B<高階指揮官放聲大笑。>$B$B這些笨蛋又一次被惡魔佔據了，現在他們都毀了！$B$B我相信我最寵信的$C會願意留下來幫我們徹底解決它們？也許這些東西其中的一樣能夠說服你？',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 12853 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12853,'zhTW','歡迎來到K3！$B$B我們來這裡是為了探勘進入風暴群山的路，並且拿取屬於我們的那一份泰坦機械。但是進展卻十分有限——豺狼人、極地狗頭人、猛獁人……附近總是有數不清的麻煩。$B$B更別提我們的飛行器引擎全都凍結了。$B$B咱們有很多工作得做——幫個忙吧，嗯？',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 12854 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12854,'zhTW','<考古學家安多林滿懷期望的看著你。>$B$B你應該要帶布萊恩一起回來的，而不是隻帶張紙回來。發生了什麼事？',0);
