INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12860,'zhTW','<布萊恩看著你握著的資料庫。>$B$B我不知道里面到底有沒有存東西！你得跟我說到底發生了什麼事。$B$B<你解釋了你的資料檢索流程。>$B$B所以成功了？至少我們可以期待米米爾隆做事很有規劃。希望他跟其他那些我聽到的守護者不一樣……',0);
