INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12901,'zhTW','這個垃圾到底是什麼！啊，全都去死吧！這沒有用。天災金屬沒辦法利用。我們到底該怎麼辦？',0);
