INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12902,'zhTW','在這座奇怪的祭壇上方漂浮著一個卷軸。這一定就是北伐軍領主蘭迪加要找的東西！',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 12903 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12903,'zhTW','他們三個做出了偉大的犧牲，我們不會忘記的。他們的死亡不會白費。我們終將獲勝！',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 12904 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12904,'zhTW','<戈爾克瀕死，並斷斷續續對你說著話。>$B$B他……他們說這些瓦古是……是巫妖王覺得沒用的傢伙們。你……你能想……想象嗎？想想……想想那些有……用的傢伙會有多強……$B$B我會在另一個世界為你祈禱，英雄……願你永遠也不會面對他們。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 12905 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12905,'zhTW','我正期待有人能來替換我的其中一個監工。你也差不多該出現了。$B$B來吧，讓我們替你安排一些工作。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 12906 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12906,'zhTW','對一個新任監工來說還算不錯了。如果你還有足夠的勇氣，我還有另一項任務要給你。',0);
