INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12907,'zhTW','如果說你剛來的時候我對你的能力有任何存疑，那麼現在都煙消雲散了——只要再努力一點，你就能夠成為我的永久成員。',0);
