INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12908,'zhTW','我就知道你會回來！快把這些鐐銬弄掉，我就會幫你找到那個地精。',0);
