INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12965,'zhTW','<佈德克拉格面色陰沉地點點頭。>$B$B你削弱了雷鑄矮人，但他們還是在持續作戰。死傷對他們來說不算什麼，但我們的衛兵卻不斷的倒下。就算死了一百個，甚至一千個鐵矮人，他們也會一直作戰下去，直到我們都被碾成粉末。',0);
