INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (12970,'zhTW','一切都安排妥當了。在我的協助下，你會在海德比武會中大放異彩，並使偉大的托里姆重返榮耀。',0);
