INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13003,'zhTW','成功了。$B$B你正面面對了死神，並且贏得了勝利。$B$B你戰勝瞭如此強大的野獸，為丹尼芬雷帶來了偉大的榮耀！',0);
