INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13005,'zhTW','這是個好的開始。但是我哥哥的部隊花不了多少時間就會重組。我們必須取得決定性的勝利。',0);
