INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13098,'zhTW','<拜基妮花了一點時間檢視這些刻了文字的石板，然後將注意力轉回你身上。>$B$B這些都是真品，$r。我會將他們納入我收集的文字中。$B$B也許我們未來能夠制止這樣的行為。',0);
