INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13121,'zhTW','非常好！原來遠古英雄伊斯卡德爾的謠言是真的。而瓦爾德瑪達本人正要前去挑戰他！$B$B如果我們想要搶先一步找到他的話，我們最好快一點！',0);
