INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13125,'zhTW','真是血戰得來的勝利，$N！這些死掉的軍官天災軍團肯定會替換。但是至少今天，天災城裡瀰漫的空氣是凝重的。',0);
