INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13128,'zhTW','<萊洛拉斯專注地聽取你的報告。>$B$B$N，這是最好的訊息。$B$B從這場衝突開始以來我們從未給予魔法之王如此的重擊。$B$B朋友，請收下巨龍軍團的謝禮。',0);
