INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13133,'zhTW','他是個很好的樣品，而且將為我們所用。$B$B現在，我們得好好運用他，以誘捕瓦爾德瑪達！',0);
