INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13134,'zhTW','<當你將結果回報給黑暗騎士，他發出一陣陰沉而空洞的笑聲，作為對你的回應及讚許。>$B$B你全身上下都充滿了成功的氣息，$N，那真是件好訊息，真的。',0);
