INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13136,'zhTW','<歐爾拉金謹慎地檢視這些金屬裂片。>$B$B你在這下面的每個食屍鬼身上，都有找到這些玩意嗎？我倒是不曾在任何與天災軍團的戰鬥中，見到類似的東西。',0);
