INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13148,'zhTW','你在哪裡找到它的？幾星期前的一次交貨中，不少這樣的項鍊被劫走了！讓我送你這個珠寶匠硬幣作為回報。',0);
