INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13157,'zhTW','在抵達冰冠堡壘的大門前，等著我們的，仍是漫長而艱難的旅途。我和銀色北伐軍的所有士兵，想對你所做的一切表達謝意。知道你將和我們一起在這塊詛咒之地上奮鬥，我們便心安不少。$B$B<大領主提里奧·弗丁向你致敬。>',0);
