INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13166,'zhTW','幹得好，死亡騎士。天災軍團的餘孽很快就會被清除，而重建的工作也將展開。$B$B我有最後一份工作得麻煩你。',0);
