INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13167,'zhTW','<基裡克斯凝視著阿努巴拉克的甲殼，他所有的眼睛發出明顯的灼熱光芒。>$B$B完成了！$B$B$r！你的名字將會被記載在我族的歷史之上。$B$B我欠了你很大一份恩情……',0);
