INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13168,'zhTW','沒什麼困難吧，嗯？任何有智力的生物，都能輕易地操縱較低等的不死生物。我懷疑，只有真正的死靈法師，能控制更強大的不死生物。不過那不成問題……',0);
