INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13204,'zhTW','你知道你帶來的那玩意是什麼嗎，$C？$B$B你獵捕的那些蠻穴野獸，根本沒有處理排洩物的方法。你該好好洗個手的……$B$B我很感謝你的點子，但是如果你要再弄那些玩意來的話，請和它們保持距離。',0);
