INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13221,'zhTW','感謝聖光。我以為卡瑪洛斯神父已經死了——甚至更糟……多虧你的勇氣與憐憫，你救回了銀色北伐軍的一個重要盟友，我和所有的十字軍向你致上謝意。',0);
