INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13224,'zhTW','<考爾姆向你敬禮。>$B$B該死的天災軍團，該死的聯盟！賀克是我們之中的精英。我們會報仇的。為了地獄咆哮，也為了部落！',0);
