INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13225,'zhTW','<巴雷特指揮官敬了個禮。>$B$B他是一個好士兵。該死的部落，該死的天災軍團！',0);
