INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13226,'zhTW','我忠誠的騎士們始終盡忠職守。看來他們蒐羅到了一位英雄！',0);
