INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13261,'zhTW','不是很好！$B$B考爾姆老是推託他太忙，我今天好不容易把他拖上來看了一會，結果你把油用光了。現在他對我很不爽，而且不准我今天再出現在他面前……$B$B回去吧，我們再試試看！',0);
