INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13266,'zhTW','讓我幫你快速瞭解下局勢，$N。$B$B幽暗城現在是戰區，藥劑師普特雷斯和惡魔瓦里瑪薩斯掌控了全域性。他們在城內採取守勢，並且用瘟疫對付我們的部隊。',0);
