INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13273,'zhTW','被毀了？這是什麼意思？營地被毀了？$B$B<布萊恩憤怒地握緊了拳頭，>$B$B那些鐵矮人會因此付出代價！但我們當前還束手無策，況且我們必須先把焦點放在完成鑰匙上，一旦我踏進奧杜爾的大廳，我會要那些爛鐵塊和他們的老大對他們所做所為給個交代！',0);
