INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13282,'zhTW','$N！我們以為你犧牲了！$B$B在爆炸中我們失去了許多人……但我們也狠狠的給了天災軍團一記。他們正準備重整旗鼓回到堡壘，正好留下一個很大的防禦漏洞，趁勝追擊的時候到了。',0);
