INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13372,'zhTW','這些聚焦之虹鑰匙原屬於最古老的一些藍龍們看護著，也只有他們受到藍龍之王瑪裡苟斯的信任。$B$B這就是我們一直等待著打擊魔法之王的時機。$B$B<紅龍女王快速地打量了以下你>$B$B你還不能使用這個鑰匙來進入聚焦之虹，但我想能分給你一點我的力量，讓你足夠將它開啟一點裂口。$B$B這足以引起瑪裡苟斯的注意了！',0);
