INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13392,'zhTW','是你，$N！我們以為你也一去不回了。$B$B你那場爆炸倒是結實地給了天災軍團一記。也差點把肯達爾上尉的眉毛給燒了……',0);
