INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13400,'zhTW','大戰之後，王子瞭解唯一束縛他的就是他是一個人類——他還是有感覺……他還是會流血……他還有……一顆心。$B$B他成為巫妖王以後的第一件事就是擺脫這些。當我們第一次見面時他將他的心投入了深淵。而你，$N則是那刻起第一個碰到的人。',0);
