INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13418,'zhTW','歡迎登上破天號。$B$B我們在這裡策劃要對阿爾薩斯發動的攻擊。我們有很多工作得做，但在我們進入實際作業以前，我們得先確定，銀色北伐軍已經得到了充分的支援……',0);
