INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13625,'zhTW','幹得好，$N。對那些習慣於步兵戰鬥的人，騎乘戰鬥可是很難上手的。我相信你會繼續精進你的技巧，應該不需要我多言。',0);
