INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13627,'zhTW','真是很棒的木材，而且價格也合理！更棒的是，那些身陷泥淖的銀色北伐軍根本不會知道。他們會得到他們珍貴的大競技場，而我則會拿到提早完工的獎金。我想這應該是個雙贏的局面吧。',0);
