INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13633,'zhTW','所以你說黑騎士的說詞全是假的？太可疑了。輕則說謊，重則謀殺。但是我們不能揭穿他，除非我們能找到他涉入這些謀殺的證據。$B$B別引起他的懷疑，$N。謹慎行事有助於我們進一步的調查。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 13634 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13634,'zhTW','所以你說黑騎士的說詞全是假的？太可疑了。輕則說謊，重則謀殺。但是我們不能揭穿他，除非我們能找到他涉入這些謀殺的證據。$B$B別引起他的懷疑，$N。謹慎行事有助於我們進一步的調查。',0);
