INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13667,'zhTW','我已經把你的名字排入名冊了，$N。作為一個勇士，你將會與其它想要在聯賽中競爭的人練習，並磨練你的騎乘戰鬥技能。一旦你證明了自己的實力，你將可以代表你的主城，進入最高層次的競賽。',0);
