INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13681,'zhTW','這樣應該夠了。別跟那些十字軍瞎說你從哪裡弄到這些石頭。我肯定他們一定會很沮喪。但你知道，反正泰坦又不會回來。我覺得這是物盡其用，拿得心安理得。做得漂亮，$N。',0);
