INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13682,'zhTW','$N，你和你的盟友幫助聯賽免於毀滅性的攻擊。雖然我們的天爪騎士非常英勇，但他們的人手幾乎都用在維持聯賽的地面安全，很難防範詛咒教派來自空中的攻擊。銀色北伐軍和所有在此參與聯賽的人都由衷地感謝你。',0);
