INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13702,'zhTW','歡迎，聯賽勇士$N。身為一位勇士，你將可以參加聯賽來爭取冠軍的資格。你也能選擇成為其它聯盟城市代表隊的勇士，甚至是總冠軍。$B$B每一位勇士將會配有一名侍從，$N，你也不例外。請讓我替你指派一位侍從，來協助你戰鬥。你將可以驕傲地帶著你所代表城市的旌旗。',0);
