INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13742,'zhTW','<勇士從你手上接過達克瑪爾之劍。>$B$B真是一把好劍，完美的平衡性。這一定能讓我在下一場比賽好好發揮。',0);
