INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13743,'zhTW','這柄劍真是名不虛傳。看來不需要修復我原有的那把劍了。冬之利刃遠遠超過我的舊劍，我會繼續使用它。我由衷地感謝你，$N。',0);
