DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 13817 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13817,'zhTW','白金圓盤完美無缺地勘合進控制檯中。它開始旋轉而白色的光束掃過圓盤。',0);
