INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13906,'zhTW','看來你們一同成長，也沒有害死對方。$B$B那麼，事情都辦妥了。我已經幫你把毒皮暴掠龍給訓練好，它已經學會順從你的哨音了。$B$B很少人能像你這麼有毅力，願意親手飼養與照料一頭毒皮暴掠龍，但你的努力非常值得。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 13908 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13908,'zhTW','大功告成。我已經讓你的毒皮暴掠龍訓練到能響應你的哨音。$B$B很少人能有足夠的毅力親手餵養一隻毒皮暴掠龍，但他們的努力是值得的。',0);
