INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13926,'zhTW','你會讓我們遠離小小狗人嗎？太好了。我們開始喜歡上你了。壞心的小小狗人搶走了所有我們心愛的玩具。',0);
