INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13927,'zhTW','你帶科科去打獵？能夠離開那個不讓科科去打獵的壞心孤兒院老女士真是太好了。',0);
