INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (13929,'zhTW','我們從不知道樹可以長那麼大！從不。也許造物主對這樹有特別的計劃？',0);
