INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (14016,'zhTW','<北伐軍萊達拉眉頭緊皺。>$B$B你覺得他們是早就計劃好的嗎？我想那不是重點，但這之後事情的進展我不喜歡，因為我有種被他們玩弄於股掌之間的感覺。無論那邊發生了什麼事，我們都必須阻止它。',0);
