INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (14095,'zhTW','我就知道海怪不是你的對手。沒有海怪攔截船隻後，那些克瓦迪爾就只剩撤退這條路了。勇士，做得好！',0);
