INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (14152,'zhTW','看來事情比我們一開始想象的還糟。但你仍舊做出了英勇的貢獻並拯救了許多浪峰號船員的生命。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 14160 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (14160,'zhTW','這份功績列表很棒，$N！你的成就將可換得可觀的獎賞。',0);
