INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (20438,'zhTW','我就知道山迪肯定會幫我們這個忙的。讓我給它附魔一下方便你使用。你越快穿上這件戰袍，我們就能越快還給山迪，畢竟萬一丟了，它的主人可接受不了。',0);
