INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (20439,'zhTW','幹得漂亮。現在寶典重回我手，我們必須儘快把它交給卡萊迪斯·亮矛，絕不能再讓它被奪日者搶走了。$B$B我確信山迪·格羅斯已經拿回了戰袍，這是給你的獎勵。',0);
