INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (24428,'zhTW','什麼？你是從哪弄到手的？她不是……算了，我想這並不重要。你應當為此獲得一些獎賞，這點毋庸置疑。',0);
