INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (24442,'zhTW','<瑪瑞爾收下了攻擊計劃與預兆水晶，仔細地檢視兩者。>$B$B幹得好，$N，幸虧你的行動早了他們一步。我相信少了這樣東西不能拖延多久，但你已經爭取到寶貴的時間，讓我們得以先行警告部落與聯盟的領袖，留意即將逼近的攻擊。',0);
