INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (24451,'zhTW','幹得漂亮。現在寶典重回我手，我們必須儘快把它交給麥雷昂·陽炎，絕不能再讓它被銀色盟約搶走了。$B$B我確信山迪·格羅斯已經拿回了戰袍，這是給你的獎勵。',0);
