INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (24589,'zhTW','艾澤拉斯的所有人民都應該慶幸大法師提邁爾預見了艾瑞達領主的到來，而你也及時趕到擊敗了他。',0);
