INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (24594,'zhTW','我簡直不敢相信我的眼睛，這居然是薩洛瑞安·尋晨者的武器？今天對於奪日者來說，對所有的辛多雷來說簡直是不可思議的一天！',0);
