INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (24595,'zhTW','真不可思議，$N。你真的做到了！所有的奎爾多雷都聽說過薩洛瑞安·尋晨者和他的武器，卻從來沒人想過這把劍還能有重鑄的一天。',0);
