INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (24802,'zhTW','又一次，復仇的機會從我指尖溜走。難以想象他現在有多強。$B$B你選擇跟著我冒險可真傻，可也證明了部落裡還是有些戰士不是無能的懦夫。烏瑟爾給我們的資訊很有可能讓我們最終擊敗阿爾薩斯，儘管單靠部落已經越來越難以實現這個目標了。$B$B上路吧，$c，我期待不久後再來見證你的英勇。',0);
