INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (24848,'zhTW','你……你不是斯內維爾。是他讓你來的？他總是遲到，我等到花都謝了……$B$B<當這女人發現你不是替斯內維爾送口信的，她淚如泉湧。>$B$B這不像是斯內維爾的，他怎麼了？',0);
