INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (24849,'zhTW','他只告訴我的就是捲款離開此地。然後他就拋棄我了，難道不是嗎？$B$B哦，$N，真是傻子才會愛上他，但我又能怎麼辦？他太迷人了！',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 24850 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (24850,'zhTW','你不是斯內維爾。他本該一小時前到這的！你對他做了什麼？$B$B<當你告訴羅卡爾你也在找斯內維爾時，她冷靜下來了。然後她淚如泉湧>$B$B這不像是斯內維爾的。你覺得他發生了什麼事？',0);
