INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (24857,'zhTW','這是非常關鍵的警報！有了這個情報我們可以召集血蹄村的兄弟來阻擊這次進攻。你救了很多$r，$N。',0);
