INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (24880,'zhTW','<卡雷苟斯發出了一聲嘆息。>$B$B太多苦難，太多痛楚。我的兄弟姐妹們承受了太多，這真是個不友好的時代。不過多虧了你們的努力，勇敢的冒險者，這個黑暗而又高尚的靈魂終於得到了平靜，不再遭受折磨。$B$B謝謝你，$C。',0);
