INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (25212,'zhTW','不可思議！$B$B資訊顯示輻射等級在我們防護服的安全範圍內。這可真是一個好訊息！',0);
