INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (25253,'zhTW','<安頓看了一遍你收集的卷軸。>$B$B到底是誰呢？知道將傳單放在一起就會引起注意，並且從舊城區的情況來看，人們似乎還挺感興趣。我們必須採取行動，不能讓他們在城市裡招到大量的追隨者。我擔心他們會利用他們的影響力在整座城市散佈恐慌，從而使暴風城陷入癱瘓。$B$B我們必須打入他們內部來儘可能瞭解更多東西。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 25254 AND `locale` = 'zhTW';
