INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (25283,'zhTW','我的天。他們反應不一？$B$B這可出乎我預料了，但我想我起碼對這個演講有點頭緒了。$B$B讓我再想想該如何措辭……',0);
