INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (25286,'zhTW','託比寫好了演講稿？讓我瞧瞧……$B$B<他開始閱讀著稿子。>真是令人心潮澎湃的作品！我知道託比是個好作家，但這次估計是他寫的最好的作品。$B$B是時候讓你去戰場了。',0);
