INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (25289,'zhTW','嗯……也就是說左腿伺服器會啟用右腿的？但我只見到左腿移動了……$B$B額，詳細的一會再說。不過有三分之二能工作：而不是隻有一半那麼糟！$B$B謝謝你為我做的測試，$N。',0);
