INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (25290,'zhTW','你好啊，朋友。我們很高興你能因為追求真理而加入我們。來吧，一會我們有的是時間談談你要了解的東西。',0);
