INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (25347,'zhTW','<你將觀察員給你的東西遞給了血衛士託雷克，然後講述了邪教徒的計劃，他的目光隨之投向了遠方。>$B$B是丘加利負責的？毫無疑問，是暮光之錘乾的！你不會是唯一一個他們在這城市散佈訊息的人。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 25348 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (25348,'zhTW','幹得不錯，$n。暮光之錘在試圖讓我們人民對抗我們的時候會三思而後行了。我相信不止一個人民受到了他們的鼓動。時代並非一帆風順，但如果我們自己都沒有榮譽可言，那我們將一無所有。',0);
DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 25351 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (25351,'zhTW','<大酋長認真聽你你講著述暮光之錘試圖摧毀奧格瑪的陰謀。>$B$B$N，你是部落的忠實成員。謝謝你將訊息帶給我。$B$B我認為他們會得到他們應得的懲罰。',0);
