INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (25380,'zhTW','做得好，$N。剛開始可能會有點彆扭，不過你要學會在公眾面前倡導我們的信仰。我們必須儘可能爭取信徒。',0);
