INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (25393,'zhTW','詛咒！我們必須退讓。瑟瑪普拉格迷失了，他也知道這一點……他在爭取最後的時間。我們要佔住表層陣地，當輻射清除後，我們會投入雙倍兵力奪回諾莫瑞根。',0);
