INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (25414,'zhTW','所以你找到了他們？可那些男人和女人為什麼不和你一起回來呢？$B$B<你告訴上尉他們不回來的各種理由。>$B$B我們無法強迫他們。我只能寄希望於邪教徒能夠及時意識到他們行為為人們帶來的傷害，並讓他們迴歸到正常生活中去。$B$B謝謝你的努力，$N，我會轉告他們家人。',0);
