INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (25415,'zhTW','做得好，$N。剛開始可能會有點彆扭，不過你要學會在公眾面前倡導我們的信仰。這是我們將真理帶給大眾的一種方式，我們必須為每個人都提供希望——因為我們要共同面對世界之末。',0);
