INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (25417,'zhTW','<你將觀察員給你的東西交給了安頓上尉，並向他解釋了這一系列的計劃。>$B$B丘加利是邪教徒的頭頭？那肯定是暮光之錘搞的鬼！我想他們會再次進攻我們，不過沒人知道會是什麼時候。$B$B你做得很出色，謝謝你為我們做得貢獻。',0);
