INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (24876,'zhTW','巨人死了？讚美聖光!$B$B前進向上的道路已經暢通無阻。收下這些戰利品作為我們感激的象徵吧，等寒冰王座化為塵土之時，我們再一同暢飲慶祝!',0);
